window.CLAIMS = {"ov.list_qureshi_four_books": {"claim_id": "ov.list_qureshi_four_books", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 2015年夏入职；他写道，入职时公司寄给他 Impro、The Looming Tower、Interviewing Users、Getting Things Done 四本书的副本，并加了限定语“我不确定他们现在是否还这样做”。", "quote_en": "I’m not sure if they still do this, but at the time when you joined they sent you a copy of Impro, The Looming Tower (9/11 book), Interviewing Users, and Getting Things Done.", "quote_zh": "我不确定他们现在是否还这样做，但在当时，新人一入职，公司就寄来一本 Impro、一本 The Looming Tower（讲 9/11 的书）、一本 Interviewing Users 和一本 Getting Things Done。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.list_qureshi_principles_pdf": {"claim_id": "ov.list_qureshi_principles_pdf", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 另写他本人拿到了后来成为 Ray Dalio《Principles》的早期 PDF；这是第一人称，没有说每个新人都拿到。", "quote_en": "I also got an early PDF version of what became Ray Dalio’s Principles. This set the tone.", "quote_zh": "我还拿到一份后来成为 Ray Dalio 的 Principles 的早期 PDF。这定下了调子。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.podcast_impro_sender_unrecovered": {"claim_id": "ov.podcast_impro_sender_unrecovered", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "在2025-05-11发布的访谈里，Qureshi 说 Impro 是某方“用来寄给别人”的书之一；转写在主语处是 [inaudible 01:28:36]，无法确认主语是 Palantir。", "quote_en": "It's one of the books that [inaudible 01:28:36] used to send to people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.podcast_impro_made_fde_read": {"claim_id": "ov.podcast_impro_made_fde_read", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "同一访谈里，Qureshi 说“他们”让每个 FDE 读 Impro，理由是帮助更好地读人、与人互动；措辞比文章里的“寄了一本”更强。", "quote_en": "And they made every kind of fully deployed engineer read that for the simple reason that I think it just helps you kind of read people better and interact with them better", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.mabrey_impro_given_on_joining": {"claim_id": "ov.mabrey_impro_given_on_joining", "unit": "ov", "source_id": "ov:mabrey-tech-republic", "claim_type": "eyewitness", "statement_zh": "Palantir 全球商务负责人 Ted Mabrey 在2025-01-09的个人 Substack 写：多年来 Palantir 员工入职时被给了 Impro 去读。", "quote_en": "For me the most instructive is in explaining why employees of Palantir for many years were given the obscure book about improvisational comedy Impro to read when they joined.", "quote_zh": "最有启发的，是解释为什么很多年里，Palantir 的员工入职时都会拿到一本冷门的即兴喜剧书 Impro 去读。", "screen_locator": "Ted Mabrey, Commentary on The Technological Republic, 2025", "review_state": "checked"}, "ov.mabrey_impro_purpose_status": {"claim_id": "ov.mabrey_impro_purpose_status", "unit": "ov", "source_id": "ov:mabrey-tech-republic", "claim_type": "eyewitness", "statement_zh": "Mabrey 的解释：读 Impro 是为了理解 status 是可用来推进局面的属性，不是定义一个人的固有属性，因此头衔无意义、局面中赢得的权威才有意义。", "quote_en": "At Palantir, we are taught we should view status as an attribute to use to advance a given situation, not an intrinsic property to define a person.", "quote_zh": "在 Palantir，我们被教导把地位看作一种属性，用来推动具体局面，而不是界定一个人的固有特质。", "screen_locator": "Ted Mabrey, Commentary on The Technological Republic, 2025", "review_state": "checked"}, "ov.agrawal_looming_mandatory": {"claim_id": "ov.agrawal_looming_mandatory", "unit": "ov", "source_id": "ov:agrawal-founder-foundry", "claim_type": "eyewitness", "statement_zh": "Apoorv Agrawal（2013–2017 年任 FDE）与 Cobi Blumenfeld-Gantz（2014–2020 年在 Palantir）2024-10-16 写道：必读材料包括 The Looming Tower，这本书突出了了解对手的重要。", "quote_en": "Mandatory reading included \"The Looming Tower\" by Lawrence Wright, which highlighted the importance of understanding your adversary.", "quote_zh": "必读材料包括 Lawrence Wright 的 The Looming Tower，它突出了了解对手的重要。", "screen_locator": "Agrawal 与 Blumenfeld-Gantz, Palantir: The Founder Foundry, 2024", "review_state": "checked"}, "ov.saraf_gtd_mandated": {"claim_id": "ov.saraf_gtd_mandated", "unit": "ov", "source_id": "ov:saraf-alums", "claim_type": "eyewitness", "statement_zh": "Sanjay Saraf（2015年入职）2024-11-13写道：Getting Things Done 先是常被推荐，后来成为新员工必读材料的一部分。", "quote_en": "Getting Things Done became a commonly recommended book and eventually became part of the mandated reading for new hires.", "quote_zh": "Getting Things Done 成了常被推荐的书，后来成为新员工必读材料的一部分。", "screen_locator": "Sanjay Saraf, Lessons from Palantir Alums, 2024", "review_state": "checked"}, "ov.saraf_gtd_bcc_mechanism": {"claim_id": "ov.saraf_gtd_bcc_mechanism", "unit": "ov", "source_id": "ov:saraf-alums", "claim_type": "eyewitness", "statement_zh": "Saraf 给出 GTD 的现场背景：对外邮件必须 BCC 全队邮件列表，重要客户会议要写 meeting report 发给很宽的列表，所以要么淹没在邮件里，要么学会设过滤规则。", "quote_en": "All email communication with the outside world had to BCC a mailing list with everyone on the team.", "quote_zh": "所有对外的邮件往来，都必须密送给一个包含全组成员的邮件列表。", "screen_locator": "Sanjay Saraf, Lessons from Palantir Alums, 2024", "review_state": "checked"}, "ov.karp_zamiska_book_via_reviews": {"claim_id": "ov.karp_zamiska_book_via_reviews", "unit": "ov", "source_id": "ov:review-robbins", "claim_type": "unresolved", "statement_zh": "两位书评人称 Karp 与 Zamiska 的《The Technological Republic》（2025年2月出版）写到新员工被给 Impro 或被鼓励运用即兴戏剧书的经验；我们没有读到书的正文。", "quote_en": "“The Improvisational Startup” introduces Palantir, noting that new employees were given Impro: Improvisation and the Theatre (1979) by Keith Johnstone, to create a culture of play, not power.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.baffler_2016_reading_list": {"claim_id": "ov.baffler_2016_reading_list", "unit": "ov", "source_id": "ov:baffler-2016", "claim_type": "unresolved", "statement_zh": "The Baffler 第32期（David V. Johnson，网页最早存档2016-09-07）称 Palantir 给新员工一份阅读清单，其中有 The Looming Tower 与 Impro；文章没有给出信源。", "quote_en": "gives its new employees a reading list. One assignment is Lawrence Wright’s The Looming Tower: Al-Qaeda and the Road to 9/11", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.hn_2016_two_books": {"claim_id": "ov.hn_2016_two_books", "unit": "ov", "source_id": "ov:hn-12416818", "claim_type": "unresolved", "statement_zh": "2016-09-02，HN 用户 ThrustVectoring 写 Impro 是 Palantir 新员工阅读清单上“两本书”之一；该用户未自称员工。", "quote_en": "There's a reason why it's one of two books on Palantir's new employee reading list.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.hn_2016_optional_by_role": {"claim_id": "ov.hn_2016_optional_by_role", "unit": "ov", "source_id": "ov:hn-12470901", "claim_type": "unresolved", "statement_zh": "2016-09-11，HN 用户 curiouscat321 回复“还有哪些书”：因岗位而异，而且都是选读；该用户未自称员工。", "quote_en": "Depends heavily on the role. It's all optional reading too.", "quote_zh": "很大程度上看岗位，而且全是选读。", "screen_locator": "Hacker News 匿名留言，2016-09-11", "review_state": "checked"}, "ov.wording_gradient": {"claim_id": "ov.wording_gradient", "unit": "ov", "source_id": "ov:hn-12470901", "claim_type": "inference", "statement_zh": "各一手叙述者对“发书”的措辞不一：Qureshi 文章是“寄了一本”，访谈是“让每个FDE读”；Agrawal 与 Blumenfeld-Gantz 是 Mandatory；Saraf 是 eventually mandated；Mabrey 是 were given ... to read；匿名 HN 是 optional、因岗位而异。所以不能写成官方课程。", "quote_en": "Depends heavily on the role. It's all optional reading too.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.official_pages_silent_on_books": {"claim_id": "ov.official_pages_silent_on_books", "unit": "ov", "source_id": "ov:palantir-life", "claim_type": "official-record", "statement_zh": "Palantir 官方 Life at Palantir 页（2026-10-17抓取）把入职描述为介绍公司、产品和各地 Palantirian 的 onboarding program，没有提到书；该页 HTML 中 book 一词出现0次。", "quote_en": "As a new hire or intern, you’ll begin your Palantir journey with an onboarding program that introduces you to our company, products, and Palantirians from across the globe.", "quote_zh": "作为新员工或实习生，你会从一个入职项目开始，了解公司、产品和来自全球各地的同事。", "screen_locator": "Palantir, Life at Palantir（2026-10-17 抓取）", "review_state": "checked"}, "ov.reposts_inflate_the_list": {"claim_id": "ov.reposts_inflate_the_list", "unit": "ov", "source_id": "ov:forwarddeployedbook", "claim_type": "inference", "statement_zh": "转贴版本（如 Deedy Das 的 LinkedIn 帖，2024-10-17）和 forwarddeployedbook.com 把 Qureshi 的一句话扩成“五本书、第一天、每个新人”；该站以现在时断言，无信源，并自称与 Palantir 无关联。", "quote_en": "Palantir gives every new hire the same five books.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "ov.cohort_and_dates": {"claim_id": "ov.cohort_and_dates", "unit": "ov", "source_id": "ov:agrawal-founder-foundry", "claim_type": "inference", "statement_zh": "几位一手叙述者自述的在 Palantir 的起始年份：Mabrey 2010，Agrawal 2013，Blumenfeld-Gantz 2014，Qureshi 与 Saraf 2015。", "quote_en": "Apoorv was a Forward Deployed Engineer at Palantir from 2013 to 2017 working primarily on the commercial side of the business", "quote_zh": null, "screen_locator": "各人自述", "review_state": "checked-with-limits"}, "ov.qureshi_why_looming_tower": {"claim_id": "ov.qureshi_why_looming_tower", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 对 The Looming Tower 的解释：公司部分是为回应 9/11，以及 Peter 认为随之而来的公民自由侵犯而创立，这段背景有价值。", "quote_en": "The Looming Tower was obvious enough – the company was founded partly as a response to 9/11 and what Peter felt were the inevitable violations of civil liberties that would follow, and the context was valuable.", "quote_zh": "The Looming Tower 的用意很明显：公司创立，部分是为了回应 9/11，以及 Peter 认为随之而来、无可避免的对公民自由的侵犯；这段背景有用。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.s1_founded_after_9_11": {"claim_id": "ov.s1_founded_after_9_11", "unit": "ov", "source_id": "ov:palantir-s1", "claim_type": "official-record", "statement_zh": "Palantir 2020-08-25提交的 S-1 写：公司创立于 9/11 袭击之后。", "quote_en": "Our company was founded in the wake of the attacks on September 11th.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.qureshi_why_impro_social_context": {"claim_id": "ov.qureshi_why_impro_social_context", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 回答“为什么是 Impro”：成功的 FDE 需要对社会语境异常敏感，要与客户或政府对口方在最高层建立信任，这常需要玩政治游戏。", "quote_en": "Being a successful FDE required an unusual sensitivity to social context – what you really had to do was partner with your corporate (or government) counterparts at the highest level and gain their trust, which often required playing political games.", "quote_zh": "做一名成功的 FDE，需要对社交场合格外敏感：真正要做的，是在最高层跟企业（或政府）的对口人结成伙伴、取得他们的信任，这常常要玩政治游戏。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.qureshi_impro_mechanistic": {"claim_id": "ov.qureshi_impro_mechanistic", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 说 Impro 在技术人群中受欢迎，部分因为它把社会行为拆成机制；他还说公司词汇里充满 Impro 式用语，例子是 casting。", "quote_en": "Impro is popular with nerds partly because it breaks down social behavior mechanistically.", "quote_zh": "Impro 受书呆子欢迎，部分是因为它把社会行为拆成了机制。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.qureshi_no_reason_for_other_three": {"claim_id": "ov.qureshi_no_reason_for_other_three", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "direct-source", "statement_zh": "Qureshi 没有为 Interviewing Users、Getting Things Done、Principles 各写一句入选理由，文中只有“这定下了基调”一句；仓库旧笔记里“Interviewing Users 对应建立信任”的说法不在原文中。", "quote_en": "This set the tone.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.lonsdale_gtd_mention": {"claim_id": "ov.lonsdale_gtd_mention", "unit": "ov", "source_id": "ov:lonsdale-8vc", "claim_type": "direct-source", "statement_zh": "Joe Lonsdale 的《Lessons from Peter Thiel》（8VC 站点标注2010-04-11）第6条用 GTD 作类比：几分钟能做完的任务不拖。", "quote_en": "Similarly, in GTD, you don’t put off tasks that only take a couple minutes.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.qureshi_fde_onsite_days": {"claim_id": "ov.qureshi_fde_onsite_days", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道，FDE 通常被期望每周3–4天到客户办公室现场工作，这在硅谷公司里极不寻常；PD 工程师则做核心产品、很少见客户。", "quote_en": "FDEs were typically expected to ‘go onsite’ to the customer’s offices and work from there 3-4 days per week, which meant a ton of travel.", "quote_zh": "FDE 通常要“到现场”，每周有 3 到 4 天在客户的办公室上班，出差非常多。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.qureshi_overfit_split": {"claim_id": "ov.qureshi_overfit_split", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 的分工描述：FDE 的任务是解决问题而不必担心过拟合，PD 的任务是把 FDE 做出的东西泛化并拿去别处卖。", "quote_en": "Your job was to solve the problem, and not worry about overfitting; PD’s job was to take whatever you’d built and generalize it, with the goal of selling it elsewhere.", "quote_zh": "你的任务是解决问题，不用担心过拟合；PD 的任务是把你做出来的东西泛化，拿去卖给别的客户。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.podcast_gain_trust": {"claim_id": "ov.podcast_gain_trust", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "访谈中他说，FDE 要见到真正向 CEO 汇报该问题的关键干系人，成为他们的朋友，获得信任。", "quote_en": "You would have to gain their trust.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.podcast_social_dynamics_hires": {"claim_id": "ov.podcast_social_dynamics_hires", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "他说后来 FDE 分两类，其中一类面试更偏“你作为人是否精明”，因为大型组织里需要有人把工作翻译给高管并处理房间里的社会动态；这个分类最初并不存在。", "quote_en": "being able to navigate the social dynamics in a room, all these are very valuable skills.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.airbus_toulouse_a350": {"claim_id": "ov.airbus_toulouse_a350", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 在文章中说，他搬到图卢兹一年，每周四天在工厂与制造人员一起工作；客户 CEO 说最大问题是 A350 的产能爬坡，他们便做软件正面解决。", "quote_en": "I moved out to Toulouse for a year and worked in the factory alongside the manufacturing people four days a week", "quote_zh": "我搬到图卢兹住了一年，每周四天在工厂里，和制造人员一起工作。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.airbus_podcast_hedges": {"claim_id": "ov.airbus_podcast_hedges", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "访谈里他的说法更保守：在法国住了约一年半（00:38:10），记不清确切数字，产能大致至少提高到4倍，且主要是客户自己做到、他们帮了忙。", "quote_en": "I don't recall the exact stat, but we did ramp up production, I think at least 4X that 1 year, which I mean obviously, they did this and we just helped with it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.data_politics_essay": {"claim_id": "ov.data_politics_essay", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 把数据整合难的主因归为组织政治：某个团队控制关键数据源，其存在理由就是做这个数据源的守门人。", "quote_en": "But often what really gets in the way is organizational politics: a team, or group, controls a key data source, the reason for their existence is that they are the gatekeepers to that data source", "quote_zh": "真正挡路的，常常是组织政治：某个团队控制着关键数据源，它存在的理由就是做这个数据源的守门人。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.data_pilot_weeks": {"claim_id": "ov.data_pilot_weeks", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "他举的后果：客户买了8–12周的试点，8–12周全花在拿数据权限上，最后一周才赶着做演示。", "quote_en": "you’d have a company buying an 8-12 week pilot, and we’d spend all 8-12 weeks just getting data access, and the final week scrambling to have something to demo.", "quote_zh": "客户买了 8 到 12 周的试点，我们把 8 到 12 周全花在拿数据权限上，最后一周手忙脚乱地凑一个演示。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.data_politics_podcast_nuance": {"claim_id": "ov.data_politics_podcast_nuance", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "eyewitness", "statement_zh": "访谈中他补充：数据被锁死有正当理由，IT 与信息安全人员并非恶意；更棘手的是技能价值依赖于当守门人的人。", "quote_en": "I think where it got a little bit more interesting was where your skills are valuable and depend on you being the gatekeeper.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.mabrey_french_restaurant": {"claim_id": "ov.mabrey_french_restaurant", "unit": "ov", "source_id": "ov:mabrey-fde-essay", "claim_type": "eyewitness", "statement_zh": "Mabrey 写道，FDE 角色据说受 Karp 观察法国优秀餐厅的启发：服务员是厨房的内在组成部分。", "quote_en": "The FDE role was famously inspired by Karp’s observation of how excellent French restaurants operate. The waitstaff is an intrinsic part of the kitchen.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.mabrey_owner_no_authority": {"claim_id": "ov.mabrey_owner_no_authority", "unit": "ov", "source_id": "ov:mabrey-fde-essay", "claim_type": "eyewitness", "statement_zh": "Mabrey 说 FDE 被训练成对客户业务的最终结果负责，像 CEO 一样行事，但没有任何权力。", "quote_en": "You must hold yourself accountable to the end results of the customers business and try to act as if you are the CEO, but with zero authority.", "quote_zh": "你必须对客户业务的最终结果负责，努力像首席执行官那样行事，但手里没有任何权力。", "screen_locator": "Ted Mabrey, Sorry, that isn’t an FDE, 2024", "review_state": "checked"}, "ov.mabrey_messy_product": {"claim_id": "ov.mabrey_messy_product", "unit": "ov", "source_id": "ov:mabrey-fde-essay", "claim_type": "eyewitness", "statement_zh": "Mabrey 称让 FDE 与核心产品团队这样配合是一种很乱的做产品方式，却是他们发现的唯一方式；他还说公司在这件事上“全世界最擅长，也做得很糟”。", "quote_en": "This is a very messy way to build product. It is also the only way we have discovered to do it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.mabrey_stratechery_secret": {"claim_id": "ov.mabrey_stratechery_secret", "unit": "ov", "source_id": "ov:stratechery-2023", "claim_type": "eyewitness", "statement_zh": "2023-06-15 的 Stratechery 访谈里，Mabrey 把 FDE 模式称为公司最大的“秘密”之一，理由是它让公司对客户的实际结果负责。", "quote_en": "we think of as one of our greatest secrets, one of the greatest features of the company", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.blog2019_delta_in_bd": {"claim_id": "ov.blog2019_delta_in_bd", "unit": "ov", "source_id": "ov:palantir-blog-2019", "claim_type": "official-record", "statement_zh": "Palantir 2019-04-08官方博客写：Delta（Forward Deployed Software Engineer）属于 Business Development，任务是为客户实现技术成果。", "quote_en": "Deltas are part of Business Development, and their mandate is to achieve technical outcomes for our customers.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.blog2019_capability_split": {"claim_id": "ov.blog2019_capability_split", "unit": "ov", "source_id": "ov:palantir-blog-2019", "claim_type": "official-record", "statement_zh": "同一官方博客用一句话区分两类：Dev 是“一种能力，多个客户”，Delta 是“一个客户，多种能力”。", "quote_en": "You can think of a Dev’s focus as “one capability, many customers,” while a Delta’s focus is “one customer, many capabilities.”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.blog2020_configure_existing": {"claim_id": "ov.blog2020_configure_existing", "unit": "ov", "source_id": "ov:palantir-blog-2020", "claim_type": "official-record", "statement_zh": "Palantir 2020-11-02官方博客（2022-06 修订）把 FDSE 描述为嵌入客户、配置 Palantir 现有软件平台去解决问题的软件工程师。", "quote_en": "A Forward Deployed Software Engineer (FDSE), or “Delta,” is a software engineer who embeds directly with our customers to configure Palantir’s existing software platforms to solve their toughest problems.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.s1_embed_with_users": {"claim_id": "ov.s1_embed_with_users", "unit": "ov", "source_id": "ov:palantir-s1", "claim_type": "official-record", "statement_zh": "S-1 写公司相信要解决最复杂的问题就必须亲身经历客户的问题，所以嵌入用户，从前线基地的特种部队到油井一线工程师。", "quote_en": "we embed with our users, from the special forces personnel in forward operating bases to oil rig engineers in the field.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.s1_bespoke_to_platform": {"claim_id": "ov.s1_bespoke_to_platform", "unit": "ov", "source_id": "ov:palantir-s1", "claim_type": "official-record", "statement_zh": "S-1 写 FDE 是发现研发机会的第一线，开发者把这些观察纳入灵活的平台，而不是写死在定制应用里。", "quote_en": "Instead of hard-wiring those observations into bespoke applications, our developers incorporate them into flexible platforms that adapt to the realities that our customers face.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.lever_blueprint": {"claim_id": "ov.lever_blueprint", "unit": "ov", "source_id": "ov:palantir-lever-fdse", "claim_type": "official-record", "statement_zh": "Palantir 现行 FDSE 招聘页（2026-10-17抓取）称这个角色是“蓝本”，公司开创了把工程师直接嵌入客户的做法。", "quote_en": "We pioneered this unique position, embedding talented engineers directly with our customers to tackle their most pressing challenges head-on.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.inf_register_contrast": {"claim_id": "ov.inf_register_contrast", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "inference", "statement_zh": "官方博客说 Delta 是部署、配置现有平台，Qureshi 与 Mabrey 说 FDE 是真正写产品、必要时造全新产品；两种语域并存，节目不应把它们并成一种说法。", "quote_en": "they were actually real engineers who could build product themselves.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "ov.inf_impro_three_readings": {"claim_id": "ov.inf_impro_three_readings", "unit": "ov", "source_id": "ov:baffler-2016", "claim_type": "inference", "statement_zh": "同一本 Impro 有三种读法：Qureshi 读作对外读房间、建立信任，Mabrey 读作对内把 status 与头衔解耦，Baffler 读作企业正统化的工具并讽之为“Palantir 的 Dianetics”。", "quote_en": "Insofar as Palantir is a cult like Scientology, Impro is its Dianetics.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.disclosure_qureshi": {"claim_id": "ov.disclosure_qureshi", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "eyewitness", "statement_zh": "Qureshi 写作时声明是个人身份、与公司已无正式关系、持有多头仓位；访谈中也强调只代表个人。", "quote_en": "I’m writing this in my personal capacity, and don’t have a formal relationship with the company anymore. I’m long $PLTR.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.unresolved_still_in_use": {"claim_id": "ov.unresolved_still_in_use", "unit": "ov", "source_id": "ov:qureshi-essay-archive", "claim_type": "unresolved", "statement_zh": "这份书单是否仍在使用不明：Qureshi 自己不确定，Mabrey 用过去式，官方页面不提。", "quote_en": "I’m not sure if they still do this", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.inf_interviewing_users_fit": {"claim_id": "ov.inf_interviewing_users_fit", "unit": "ov", "source_id": "ov:lenny-podcast-transcript", "claim_type": "inference", "statement_zh": "Interviewing Users 为何入选没有任何一手理由；它与 FDE 工作的契合只是我们的推论：Qureshi 描述的 FDE 循环确实包含“见用户、谈他们的问题”。", "quote_en": "meet the people that are going to become your users, talk to them about their problems", "quote_zh": "去见将来会成为你用户的人，和他们谈他们的问题。", "screen_locator": "Nabeel Qureshi, Lenny’s Podcast, 2025, 00:24:26", "review_state": "checked"}, "ov.role_coverage_gap": {"claim_id": "ov.role_coverage_gap", "unit": "ov", "source_id": "ov:hn-12470901", "claim_type": "unresolved", "statement_zh": "所有一手叙述者都来自 BD/FDE 或商务侧，没有 PD 工程师或非美国办公室的一手说法，所以不能断言各岗位、各办公室一致。", "quote_en": "Depends heavily on the role. It's all optional reading too.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "iu.hh-premium": {"claim_id": "iu.hh-premium", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "第 1 章开篇案例：一家公司打算把安全帽这种大宗安全商品（commodity safety product）做成高端产品（premium product）。", "quote_en": "turn a commodity safety product—the hard hat—into a premium product", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.hh-method": {"claim_id": "iu.hh-method", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者访谈佩戴安全帽工作的人时，没有请他们评价客户设想的功能，而是笼统地问他们的工作。", "quote_en": "I didn’t ask them to evaluate the features my client had been considering. Instead, I asked them generally about their work", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.hh-finding": {"claim_id": "iu.hh-finding", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "受访者最在意的是另一类问题：离开工地去吃午饭时，穿着显眼的亮色安全装备混在别人中间感到尴尬。", "quote_en": "They talked about leaving the job site to get lunch (for example) and how awkward they felt among other people while dressed in their prominent, brightly colored safety equipment.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.hh-not-tedx": {"claim_id": "iu.hh-not-tedx", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者先设想了一个演讲式的圆满版本：团队为新机会兴奋、推翻旧计划、最终大赚一笔，随后明说事情并不是这样发展的。", "quote_en": "But you know that isn’t really how these things play out!", "quote_zh": "可你也知道，这类事情其实不是这么发展的！", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "iu.hh-stop": {"claim_id": "iu.hh-stop", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "访谈揭示了继续原有设想的重大商业风险，客户因此停止了加功能安全帽的产品开发。", "quote_en": "In these interviews, we uncovered a significant business risk in pursuing their existing idea, so they stopped product development for their hard hat with extra functionality.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.hh-fashion-dropped": {"claim_id": "iu.hh-fashion-dropped", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "访谈还指出另一个机会（解决社交表现问题的安全帽），但客户判断它不符合自身的技术与文化能力，选择不做时尚安全帽。", "quote_en": "That wouldn’t have fit with their organization’s technical or cultural competencies, so they chose to avoid the business risk of developing a fashionable hard hat.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.hh-no-product": {"claim_id": "iu.hh-no-product", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者对这次研究结果的概括是：访谈为客户“不把任何产品推向市场”的决定提供了依据。", "quote_en": "What we learned from these interviews informed their decision not to bring any product to market.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.researcher-job": {"claim_id": "iu.researcher-job", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者把用户研究者的工作界定为：收集用户信息，为设计、产品或组织其他方面的关键决策提供依据。", "quote_en": "We gather information about users in order to inform critical decisions about design, product, or other parts of the business or organization.", "quote_zh": "我们收集关于用户的信息，是为了给设计、产品，或者企业与组织其他方面的关键决定提供依据。", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "iu.pain-foraging": {"claim_id": "iu.pain-foraging", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者批评把访谈的目标说成“发现用户痛点”：这是把用户研究错当成一种觅食活动。", "quote_en": "Often, the stated goal of interviewing users is to uncover their pain points. This approach mistakenly characterizes research with users as a sort of foraging activity", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pain-dig": {"claim_id": "iu.pain-dig", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者认为洞察不会自己跳出来，需要花力气去挖，而挖需要计划和审慎。", "quote_en": "Insights don’t simply leap out at you. You need to work hard and dig for them, which takes planning and deliberation.", "quote_zh": "洞见不会自己跳到你面前。你得下功夫去挖，而挖需要计划，也需要斟酌。", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "iu.pain-not-painful": {"claim_id": "iu.pain-not-painful", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "设计师、工程师这类解决问题的职业所看到的“痛点”，对当事人本身未必那么痛。", "quote_en": "what people in problem-solving professions (such as designers and engineers) see as “pain points” aren’t necessarily that painful for people", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.satisficing-def": {"claim_id": "iu.satisficing-def", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "书中把 satisficing 定义为人们对“够用就行”的方案的容忍乃至欣然接受，并称该词由 Herbert Simon 于 1956 年提出，由 satisfy 与 suffice 合成。", "quote_en": "The term satisficing, coined by Herbert Simon in 1956 (combining satisfy and suffice), refers to people’s tolerance—if not overall embracing—of “good-enough” solutions.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.airplane-sling": {"claim_id": "iu.airplane-sling", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者在长途航班上看到前排乘客用飞机毯的塑料袋给 iPhone 做了一个粗糙的吊带，用来边挂边看。", "quote_en": "I noticed that a passenger in the row in front of me had fashioned a crude sling for their iPhone using the plastic bag that the airplane blanket came in.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.airplane-turn": {"claim_id": "iu.airplane-turn", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者对这个自制吊带的反应是先批评它又丑又不雅，后来转而认为它自有其美。", "quote_en": "Initially, I was critical of the ugly, inelegant result. But eventually, I realized it was beautiful in its own way", "quote_zh": "起初，我对这个又丑又笨拙的成品颇有微词。可后来我意识到，它自有一种美", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "iu.satisficing-examples": {"claim_id": "iu.satisficing-examples", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者称每个研究项目都会遇到 satisficing，举例包括：塞满不配套盖子的食物盒抽屉、没拆封的汽车手册、缠在一起又太短的产品连接线。", "quote_en": "an overflowing drawer of mismatched food container lids, a not-yet-unwrapped car manual, and tangled, too-short cables connecting products are all “good-enough” examples of satisficing", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.satisficing-effort": {"claim_id": "iu.satisficing-effort", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者的解释是：人们觉得这个“假定的问题”带来的痛，比自己去解决它所要花的力气更轻。", "quote_en": "people find the pain of this putative problem to be less acute than the effort required by them to solve it", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.reframes": {"claim_id": "iu.reframes", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说访谈对催生 reframe 特别有效，reframe 指把最初的问题整个翻过来的关键视角转变。", "quote_en": "interviewing customers is tremendous for driving reframes, which are crucial shifts in perspective that flip an initial problem on its head", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-summary": {"claim_id": "iu.plan-summary", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说研究计划应概括项目在当时的理解，内容包括业务问题、研究问题和已商定的研究方法。", "quote_en": "A plan should summarize the project as you understand it at the time, including the business problem, the research questions, and the agreed-upon research method.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-plus-one": {"claim_id": "iu.plan-plus-one", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说高层研究计划有三项要素，外加一位“特别来宾”。", "quote_en": "here let’s consider the three (plus one special guest) elements of a high-level plan.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-inward-outward": {"claim_id": "iu.plan-inward-outward", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "业务问题向内看，是关于组织自己；研究问题向外看，是关于用户。", "quote_en": "Whereas the business problem looks inward, the research question looks outward—in other words, the business problem is about you and the research question is about your users", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-participant-guest": {"claim_id": "iu.plan-participant-guest", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "参与者提问（Participant Questions）不算高层计划的一项，放在这一章是因为讨论研究问题时常会滑向想问参与者的具体问题。", "quote_en": "This isn’t really part of the high-level plan, but it’s included here because discussion about the research question sometimes drifts into specific questions that people imagine asking participants.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-nonlinear-starts": {"claim_id": "iu.plan-nonlinear-starts", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说项目可能从计划三项中的任何一项起步：给出情况、给出研究问题、或直接给出研究方法与时限。", "quote_en": "You may be asked Here’s the situation, how can research help us? Or We need to learn such-and-such about these users. Or Can we complete this method of research within this time frame?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-backward-why": {"claim_id": "iu.plan-backward-why", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "被给定研究问题时，先问为什么需要这条信息；被给定研究方法时，先问对方希望学到什么，再问为什么需要这条信息。", "quote_en": "If you’re given a research question, ask why that information is needed. If you’re given a research method, ask what they hope to learn, and then ask why that information is needed.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-alignment": {"claim_id": "iu.plan-alignment", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者要求计划各部分对齐：方法必须产出所需信息，所需信息必须服务于团队打算采取的行动。", "quote_en": "the method has to produce the information that is needed, and the information that is needed should be in support of the actions the team plans to take", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.plan-prescribed": {"claim_id": "iu.plan-prescribed", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者劝研究者不要接受与所需结果不匹配的指定方法，理由是最终交不出结果时责任会落到研究者身上。", "quote_en": "Don’t agree to use a prescribed method that doesn’t align with the necessary results, because the blame will fall to you at the end when you can’t deliver.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.misalignment-sidebar": {"claim_id": "iu.misalignment-sidebar", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "“Uncover Misalignment Early” 插叙：作者与利益相关方做第二场启动工作坊时，一位利益相关方开场就说他们已经在写代码做解决方案了。", "quote_en": "Just so you know, we’re already coding a solution.", "quote_zh": "先跟你说一声，我们已经在写解决方案的代码了。", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "iu.insight-vs-persuade": {"claim_id": "iu.insight-vs-persuade", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者在日本旁观客户的一项研究：用户被请进场地，看漂亮的泪滴形墨盒与旧款墨盒，人人更爱新款；作者认为无论用什么方法，这里都得不到洞察。", "quote_en": "Regardless of method, there was no insight to be gained here.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "iu.limit-depth": {"claim_id": "iu.limit-depth", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者明说访谈并不适合所有问题：它偏重深度而非样本量，只有在不需要统计显著数据时才该用。", "quote_en": "Interviewing isn’t the right approach for every problem. Because it favors depth over sample size, use interviewing when you don’t need statistically significant data.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.limit-tally": {"claim_id": "iu.limit-tally", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者承认访谈是半结构化的，每场都不同，因此很难客观地对整个样本做数据点统计。", "quote_en": "Being semi-structured, each interview will be unique and reveal something new about what you’re trying to understand (but it can be challenging to objectively tally data points across the sample).", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.limit-future": {"claim_id": "iu.limit-future", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说人们不擅长预测自己未来的行为，对全新的假设情境尤其如此，并指向第 4 章中的“Manage Bias”一节。", "quote_en": "People are not good at predicting their future behavior, especially not for brand-new, hypothetical situations (see “Manage Bias” in Chapter 4).", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.limit-pricing": {"claim_id": "iu.limit-pricing", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者说，问“这个你愿意付多少钱”得不到可用于定价策略的数字，但能了解对方给出该数字的理由，或听到对价值的深思。", "quote_en": "You won’t get a number that is helpful for your pricing strategy, but you can learn about their rationale for that number or hear a thoughtful reflection about perceived value.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.toc-2e-ch1-5": {"claim_id": "iu.toc-2e-ch1-5", "unit": "iu", "source_id": "iu:rosenfeld-book-page-2e", "claim_type": "direct-source", "statement_zh": "出版方目录：第 2 版有前言（Jamika D. Burge）与第 1 至 5 章，章名依次为 Interviewing Addresses a Business Need、Research Logistics、Contextual Methods—More Than Just Asking Questions、The Successful Fieldwork Experience、Best Practices for Interviewing。", "quote_en": "Foreword by Jamika D. Burge Chapter 1: Interviewing Addresses a Business Need Chapter 2: Research Logistics Chapter 3: Contextual Methods—More Than Just Asking Questions Chapter 4: The Successful Fieldwork Experience Chapter 5: Best Practices for Interviewing", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.toc-2e-ch6-10": {"claim_id": "iu.toc-2e-ch6-10", "unit": "iu", "source_id": "iu:rosenfeld-book-page-2e", "claim_type": "direct-source", "statement_zh": "出版方目录：第 6 至 10 章依次为 The Intricacies of Asking Questions、Better Interviews、Documenting the Interview、Making Sense of Your Data、Making an Impact with Your Research。", "quote_en": "Chapter 6: The Intricacies of Asking Questions Chapter 7: Better Interviews Chapter 8: Documenting the Interview Chapter 9: Making Sense of Your Data Chapter 10: Making an Impact with Your Research", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pubinfo-2e": {"claim_id": "iu.pubinfo-2e", "unit": "iu", "source_id": "iu:rosenfeld-book-page-2e", "claim_type": "direct-source", "statement_zh": "第 2 版 2023 年 10 月出版，平装 276 页。", "quote_en": "Published: October 2023 Paperback: 276 pages", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pub-new-chapters": {"claim_id": "iu.pub-new-chapters", "unit": "iu", "source_id": "iu:rosenfeld-book-page-2e", "claim_type": "direct-source", "statement_zh": "出版方称第 2 版新增两章：一章讲分析与综合并分享研究结果，另一章讲让研究在组织中产生影响。", "quote_en": "This edition features two new chapters: one about analysis and synthesis and sharing research results, and another about ensuring that your user research efforts will have an impact on your organization.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.toc-1e-pubinfo": {"claim_id": "iu.toc-1e-pubinfo", "unit": "iu", "source_id": "iu:rosenfeld-book-page-1e", "claim_type": "direct-source", "statement_zh": "第 1 版 2013 年 5 月出版，平装 176 页。", "quote_en": "Published: May 2013 Paperback: 176 pages", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.toc-1e-ch1": {"claim_id": "iu.toc-1e-ch1", "unit": "iu", "source_id": "iu:rosenfeld-book-page-1e", "claim_type": "direct-source", "statement_zh": "第 1 版第 1 章题为 The Importance of Interviewing in Design，第 2 章为 A Framework for Interviewing，与第 2 版第 1 章 Interviewing Addresses a Business Need 不同。", "quote_en": "Chapter 1: The Importance of Interviewing in Design Chapter 2: A Framework for Interviewing", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.toc-1e-ch9": {"claim_id": "iu.toc-1e-ch9", "unit": "iu", "source_id": "iu:rosenfeld-book-page-1e", "claim_type": "direct-source", "statement_zh": "第 1 版共 9 章，最后一章已题为 Making an Impact with Your Research。", "quote_en": "Chapter 9: Making an Impact with Your Research", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ux-chapters-in-1e": {"claim_id": "iu.ux-chapters-in-1e", "unit": "iu", "source_id": "iu:uxpodcast-328-transcript", "claim_type": "direct-source", "statement_zh": "作者说，分析与综合、产生影响这两个主题在第 1 版里已经有，但只是收尾时点到为止。", "quote_en": "they were kind of in the first edition, they were kind of like, ‘Alright, everybody time to wrap this thing up. Let me just kind of acknowledge there’s more.’", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.qu-list": {"claim_id": "iu.qu-list", "unit": "iu", "source_id": "iu:qureshi-reflections-2024", "claim_type": "direct-source", "statement_zh": "Qureshi 回忆，入职时公司寄给新人四本书：Impro、The Looming Tower、Interviewing Users、Getting Things Done。", "quote_en": "at the time when you joined they sent you a copy of Impro, The Looming Tower (9/11 book), Interviewing Users, and Getting Things Done", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.qu-joined": {"claim_id": "iu.qu-joined", "unit": "iu", "source_id": "iu:qureshi-reflections-2024", "claim_type": "direct-source", "statement_zh": "Qureshi 于 2015 年夏入职，起初在新开的伦敦办公室。", "quote_en": "I joined in summer 2015, initially in the newly-opened London office", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.qu-asin": {"claim_id": "iu.qu-asin", "unit": "iu", "source_id": "iu:qureshi-reflections-2024", "claim_type": "inference", "statement_zh": "Qureshi 文中 Interviewing Users 的链接指向 Amazon 条目 193382011X，它是第 1 版平装（ISBN-13 9781933820118）的 ISBN-10；第 2 版 2023 年 10 月才出版，晚于他 2015 年入职。", "quote_en": "https://www.amazon.com/Interviewing-Users-Uncover-Compelling-Insights/dp/193382011X", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.qu-no-reason": {"claim_id": "iu.qu-no-reason", "unit": "iu", "source_id": "iu:qureshi-reflections-2024", "claim_type": "unresolved", "statement_zh": "Qureshi 在这段里没有说明为什么书单里有 Interviewing Users，只说这套书“定了调”，并只对 The Looming Tower 与 Impro 作了说明。", "quote_en": "This set the tone.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-interpret": {"claim_id": "iu.ws1-interpret", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "复盘表 1 的 HOME AND HOUSEHOLD 栏标为 interpret，首问却是“描述房子和院子”，随后问研究者对住在那里的人有什么印象。", "quote_en": "HOME AND HOUSEHOLD -- interpret Describe the house and yard. What impression did you get of the people who reside there?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-describe": {"claim_id": "iu.ws1-describe", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "复盘表 1 的 VEHICLE HISTORY AND PROCESS 栏标为 describe，首问是平实的事实：他们有哪些车辆。", "quote_en": "VEHICLE HISTORY AND PROCESS -- describe What are their vehicles?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-describe-to-you": {"claim_id": "iu.ws1-describe-to-you", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "同一份表里标为 describe 的栏，末一问请研究者自己判断：对你来说，他们的购车故事里哪些点关键或出人意料。", "quote_en": "What were some key or surprising points to you about their vehicle-purchase story?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-report": {"claim_id": "iu.ws1-report", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "复盘表 1 的 CONCEPT 栏标为 report，首项是记录受访者对概念的反应。", "quote_en": "CONCEPT -- report Concept reactions", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-report-redesign": {"claim_id": "iu.ws1-report-redesign", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "report 栏内还问：针对这位受访者，你的概念要重新设计或改进什么。", "quote_en": "What about your concept would you redesign or refine specifically for this person?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws2-getting-describe": {"claim_id": "iu.ws2-getting-describe", "unit": "iu", "source_id": "iu:pdf-debrief-ws2-2012", "claim_type": "direct-source", "statement_zh": "复盘表 2 的 GETTING TO KNOW YOU 栏标为 describe，首问是描述我们谈话的这个人。", "quote_en": "GETTING TO KNOW YOU-- describe Describe the person we spoke to.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws2-surprise": {"claim_id": "iu.ws2-surprise", "unit": "iu", "source_id": "iu:pdf-debrief-ws2-2012", "claim_type": "direct-source", "statement_zh": "复盘表 2 的 LIFE WITH DEVICE 栏末问把受访者的意外和研究者自己的意外并列写出：他们被什么惊到，你被什么惊到。", "quote_en": "What surprised them? What surprised you?", "quote_zh": "他们被什么惊到了？你被什么惊到了？", "screen_locator": "Portigal Consulting, Debriefing Worksheet 2, 2012", "review_state": "checked"}, "iu.ws2-assess": {"claim_id": "iu.ws2-assess", "unit": "iu", "source_id": "iu:pdf-debrief-ws2-2012", "claim_type": "direct-source", "statement_zh": "复盘表 2 的 PROTOTYPE 栏标为 assess，首问是他们喜欢原型的什么。", "quote_en": "PROTOTYPE -- assess What did they like about PROTOTYPE?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws2-assess-plusminus": {"claim_id": "iu.ws2-assess-plusminus", "unit": "iu", "source_id": "iu:pdf-debrief-ws2-2012", "claim_type": "direct-source", "statement_zh": "assess 栏要求用 + 和 - 把受访者喜欢与不喜欢的点列成清单。", "quote_en": "(use + and - here to make a bulleted list of answers)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws2-immediately": {"claim_id": "iu.ws2-immediately", "unit": "iu", "source_id": "iu:pdf-debrief-ws2-2012", "claim_type": "direct-source", "statement_zh": "复盘表 2 要求访谈一结束就由两位访谈者一起填写，并说该表是之后协作复盘与分析的关键资料。", "quote_en": "Fill this out immediately after the interview, together with both interviewers. This document will serve as key resources for the collaborative fieldwork debrief and analysis so please be thoughtful and thorough.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.res-initial-takeaways": {"claim_id": "iu.res-initial-takeaways", "unit": "iu", "source_id": "iu:portigal-resources-page-ia", "claim_type": "direct-source", "statement_zh": "作者在资源页对两份复盘表的自述是：访谈后立即使用、用来捕捉最初的关键收获的两种示例。", "quote_en": "two different examples of worksheets to be used right after the interview in order to capture some of the key initial takeaways", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.d23-labels-persist": {"claim_id": "iu.d23-labels-persist", "unit": "iu", "source_id": "iu:pdf-debrief-2023", "claim_type": "direct-source", "statement_zh": "2023 年 7 至 8 月在作者站点发布的 “Debriefing Worksheet A” 把两张旧表合并为一份 3 页 PDF，仍保留 describe/interpret/report/assess 后缀。", "quote_en": "PROTOTYPE -- assess What did they like about the PROTOTYPE?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.d23-unlabelled": {"claim_id": "iu.d23-unlabelled", "unit": "iu", "source_id": "iu:pdf-debrief-2023", "claim_type": "direct-source", "statement_zh": "合并版里 LIFE WITH PRODUCT 栏没有 describe 之类的后缀。", "quote_en": "LIFE WITH PRODUCT How are they using the PRODUCT?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.gb-debrief-frame": {"claim_id": "iu.gb-debrief-frame", "unit": "iu", "source_id": "iu:greenbook-podcast-2024", "claim_type": "direct-source", "statement_zh": "作者说复盘时听同伴听到了什么、什么让他们意外，能让他看出他们怎样框定世界、什么信息对他们有用。", "quote_en": "when I hear what they heard and what surprises them, I understand, yeah, how they’re framing the world, what’s relevant information", "quote_zh": "我听到他们听到了什么、被什么惊到，就明白了，嗯，他们是怎样框定这个世界的，哪些信息对他们来说要紧", "screen_locator": "Steve Portigal, Greenbook Podcast, 2024", "review_state": "checked"}, "iu.gb-debrief-gap": {"claim_id": "iu.gb-debrief-gap", "unit": "iu", "source_id": "iu:greenbook-podcast-2024", "claim_type": "direct-source", "statement_zh": "作者说若同伴带走的内容有缺口，他就知道回头汇报时要强调那一点，因为有些结论对他显而易见而对对方不是。", "quote_en": "if there’s a gap in what they took away, then I now know I need to kind of emphasis that because it’s—there’s a takeaway that’s obvious to me that isn’t to them", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.gb-debrief-formality": {"claim_id": "iu.gb-debrief-formality", "unit": "iu", "source_id": "iu:greenbook-podcast-2024", "claim_type": "direct-source", "statement_zh": "作者说用表格做复盘带一点“仪式”，既提醒自己认真对待，也向协作者表明他看重他们的意见。", "quote_en": "a formality to it that reminds me to take it seriously and that shows my collaborators that I value what they have to say", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.gb-debrief-not-natural": {"claim_id": "iu.gb-debrief-not-natural", "unit": "iu", "source_id": "iu:greenbook-podcast-2024", "claim_type": "direct-source", "statement_zh": "作者承认给活动配模板不是他的天性，他更愿意直接聊。", "quote_en": "it’s not my natural way of being to have a template for an activity. I’d rather just chat.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ama-separate": {"claim_id": "iu.ama-separate", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者说他把“处理经历”和“处理数据”分开。", "quote_en": "I separate the “processing the experience” and “processing the data.”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ama-worksheet-optional": {"claim_id": "iu.ama-worksheet-optional", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者说访谈后他可能做复盘表，但通常不做。", "quote_en": "After an interview, I might do a debrief worksheet – but typically not.", "quote_zh": "访谈之后，我可能会填一张复盘表，但通常不填。", "screen_locator": "Steve Portigal, What Users Do AMA, 2017", "review_state": "checked"}, "iu.ama-forced-analysis": {"claim_id": "iu.ama-forced-analysis", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者每天结束时写的一两段速记，是讲故事式的练习、一种被迫的分析（把大块内容提炼成小块），同时把田野工作分享给团队。", "quote_en": "It’s meant to be a storytelling exercise, it’s a forced analysis (take a large thing and pull out some smaller bits) – and it shares the fieldwork with the rest of the team.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.fg12-roles": {"claim_id": "iu.fg12-roles", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2012", "claim_type": "direct-source", "statement_zh": "2012 版现场参与说明规定：作者一方是 lead interviewer，随行的客户是 second interviewer，类比《法律与秩序》里的 second chair。", "quote_en": "One of us (Portigal Consulting) will be the lead interviewer. You will be second interviewer. (Kind of like “second chair” on Law and Order!)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.fg12-hold-questions": {"claim_id": "iu.fg12-hold-questions", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2012", "claim_type": "direct-source", "statement_zh": "现场参与说明要求随行者把问题写下来、等合适的时机再问，并把访谈比作书的章节。", "quote_en": "Write down and hold your questions for the appropriate time. Interviews unfold like the chapters of a book.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.fg12-experts": {"claim_id": "iu.fg12-experts", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2012", "claim_type": "direct-source", "statement_zh": "现场参与说明要求随行者把受访者当作专家，自己不是专家。", "quote_en": "We aren’t the experts. The people we are interviewing are the experts.", "quote_zh": "我们不是专家。我们访谈的人才是专家。", "screen_locator": "Portigal Consulting, A Guide to Participating in Fieldwork, 2012", "review_state": "checked"}, "iu.fg12-bus": {"claim_id": "iu.fg12-bus", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2012", "claim_type": "direct-source", "statement_zh": "现场参与说明用乘车体验举例：问“你喜欢乘车的三件事是什么”是较差问法，问“能讲讲你乘车的经历吗”是较好问法。", "quote_en": "Less Good: “What are three things you liked about using the bus?” Good: “Can you tell me about your experience using the bus?”", "quote_zh": "较差：“你喜欢坐公交的哪三件事？” 较好：“能跟我讲讲你坐公交的经历吗？”", "screen_locator": "Portigal Consulting, A Guide to Participating in Fieldwork, 2012", "review_state": "checked"}, "iu.fg23-bus-better": {"claim_id": "iu.fg23-bus-better", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2023", "claim_type": "direct-source", "statement_zh": "2023 版在同一例子里新增第三档 Better：“你乘公共交通吗？”", "quote_en": "Better: “Do you use public transportation?”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.fg23-after": {"claim_id": "iu.fg23-after", "unit": "iu", "source_id": "iu:pdf-fieldwork-guide-2023", "claim_type": "direct-source", "statement_zh": "2023 版新增 “After the Interview” 一节：访谈后找时间一起复盘，说一场访谈看不出主题或模式，随着研究推进才开始讨论浮现的东西。", "quote_en": "While one interview doesn’t reveal a theme or a pattern, as the study proceeds, we may start to discuss what is coming up.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ama-fieldwork-purpose": {"claim_id": "iu.ama-fieldwork-purpose", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者自述这份现场参与说明是一两页的东西，用来帮人在加入（而不是主持）用户研究访谈时做好。", "quote_en": "My consulting guide to fieldwork is a one or two pager that is meant to help people do well when they are joining in (NOT LEADING) user research interviews.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.st23-success": {"claim_id": "iu.st23-success", "unit": "iu", "source_id": "iu:pdf-stakeholder-guide-2023", "claim_type": "direct-source", "statement_zh": "2023 年的 Stakeholder Interview Guide 里有一问：对你而言，这个项目要怎样才算成功。", "quote_en": "What will it look like for you, for this project to be considered successful?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ama-bias": {"claim_id": "iu.ama-bias", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者说偏见当然要在意，但大家总把它当作头号担心；这本来就是带偏见的工作。", "quote_en": "I think bias is obviously a concern but it comes up so often as the main thing people are concerned about. This is totally biased work!", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ama-articulation": {"claim_id": "iu.ama-articulation", "unit": "iu", "source_id": "iu:portigal-ama-whatusersdo-2017", "claim_type": "direct-source", "statement_zh": "作者说招募时有时会按一定的舒适度筛掉人，他称之为“articulation screen”。", "quote_en": "Sometimes we make sure in our recruiting process that we screen out people who aren’t already meeting a certain comfort level – “the articulation screen”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.sc12-articulation": {"claim_id": "iu.sc12-articulation", "unit": "iu", "source_id": "iu:pdf-screener-2012", "claim_type": "direct-source", "statement_zh": "示例 screener 的末题让招募者请对方讲一次近期买菜的经历，若对方不能无提示地讲出两三句，就必须终止。", "quote_en": "IF RESPONDENT DOES NOT GIVE A TWO OR THREE SENTENCE, UNPROMPTED ANSWER, YOU MUST TERMINATE.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ig12-brackets": {"claim_id": "iu.ig12-brackets", "unit": "iu", "source_id": "iu:pdf-interview-guide-2012", "claim_type": "direct-source", "statement_zh": "访谈提纲里用方括号写给访谈者的动作提示（如追问不同的阅读类型、地点、动机），与要说出口的编号问题区分开。", "quote_en": "[Probe for different types of reading, locations, motivations, etc.]", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ig12-sections": {"claim_id": "iu.ig12-sections", "unit": "iu", "source_id": "iu:pdf-interview-guide-2012", "claim_type": "direct-source", "statement_zh": "提纲按带时长的节组织：Introduction 5 分钟、Overview 10、Exploring Specifics 10、Environment 5、Printed Book 或 eBook Reader 参与者各 10、Choosing Reading Material 10、The Future 15、Wrap Up 5。", "quote_en": "Exploring Specifics (locations, subject matter, motivations) (10 min)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.tl12-structure": {"claim_id": "iu.tl12-structure", "unit": "iu", "source_id": "iu:pdf-topline-2012", "claim_type": "direct-source", "statement_zh": "Reading Ahead 顶部摘要以结论式标题为一条，其下列带名字的受访者行为与原话，例如 “Reading and Books are not always one and the same”。", "quote_en": "Reading and Books are not always one and the same", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ra-selffunded": {"claim_id": "iu.ra-selffunded", "unit": "iu", "source_id": "iu:portigal-reading-ahead-posts", "claim_type": "direct-source", "statement_zh": "Reading Ahead 是作者咨询公司自费做的、没有客户的项目。", "quote_en": "For our self-funded Reading Ahead project, we had no client", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pp-laser": {"claim_id": "iu.pp-laser", "unit": "iu", "source_id": "iu:portigal-blog-pain-points-2010", "claim_type": "direct-source", "statement_zh": "作者 2010 年就写过：只盯着“什么对你不好用”这个问题，会错过各种机会。", "quote_en": "if you are laser-focused on the question “What’s not working for you?” you’ll miss all sorts of opportunities", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pp-works-well": {"claim_id": "iu.pp-works-well", "unit": "iu", "source_id": "iu:portigal-blog-pain-points-2010", "claim_type": "direct-source", "statement_zh": "作者的做法是在研究中也请人谈生活中运转得很好的事，而不只问痛点。", "quote_en": "In our research engagements we like to include discussion with people about the things in their lives that are working really well for them", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.norman-viable": {"claim_id": "iu.norman-viable", "unit": "iu", "source_id": "iu:portigal-blog-norman-2009", "claim_type": "direct-source", "statement_zh": "作者 2009 年承认，他们指给客户的机会很多没有被充分探索，几乎没有一个走到解决让它可行的技术与商业难题的地步。", "quote_en": "Many of those opportunities do not get fully explored, and almost none to the point of solving the ridiculously challenging technical and business challenges to make them viable.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.mtp-3areas": {"claim_id": "iu.mtp-3areas", "unit": "iu", "source_id": "iu:portigal-mtp-2019-writeup", "claim_type": "direct-source", "statement_zh": "2019 年 Mind the Product 演讲的文字整理把研究规划分为三块：业务问题、研究目标、参与者提问，与第 2 版第 1 章的三要素（业务问题、研究问题、研究方法）切法不同。", "quote_en": "Business question: What challenge does the business face? Research objective: What do we hope to learn to help us answer that business question? Participant questions: What questions can we ask customers to help us achieve that research objective?", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "iu.book2-resources": {"claim_id": "iu.book2-resources", "unit": "iu", "source_id": "iu:portigal-book-page-2e", "claim_type": "direct-source", "statement_zh": "作者站点第 2 版图书页列出配套资源：现场参与指南、利益相关方访谈指南、示例 screener、示例访谈提纲、观察框架、观察指南和复盘表。", "quote_en": "A guide to participating in fieldwork Stakeholder interview guide Sample screener Sample interview guide Observation frameworks Observation guide Debrief worksheets", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.team-shared-experience": {"claim_id": "iu.team-shared-experience", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者称访谈给产品开发团队带来一种共同的、常有激励作用的经历。", "quote_en": "Interviewing creates a shared bonding experience, often a galvanizing one, for the product development team", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.reframes-together": {"claim_id": "iu.reframes-together", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者希望更大的团队能一起看到 reframe 并共同决定怎么办，而不是由研究团队回头向发起人宣布“真正的问题是别的”。", "quote_en": "Ideally, the broader team is collaborative enough that they will see these reframes together and can decide what to do about them.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.stakeholder-6-8": {"claim_id": "iu.stakeholder-6-8", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "作者通常访谈 6 至 8 位利益相关方（有些客户要求翻倍），每场一对一，30 至 60 分钟。", "quote_en": "I typically aim for 6–8 stakeholders, although some clients ask for twice that amount. These are one-on-one conversations that run between 30 and 60 minutes", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.pp-primary-functions": {"claim_id": "iu.pp-primary-functions", "unit": "iu", "source_id": "iu:portigal-blog-pain-points-2010", "claim_type": "direct-source", "statement_zh": "作者在批评只盯痛点的同一篇文章里也承认：产品必须把主要功能做得相当好，否则没人会买。", "quote_en": "Of course no one is going to buy your company’s toilet if it leaks or doesn’t flush – products need to perform their primary functions reasonably well", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.ws1-painpoints": {"claim_id": "iu.ws1-painpoints", "unit": "iu", "source_id": "iu:pdf-debrief-ws1-2012", "claim_type": "direct-source", "statement_zh": "作者自己的复盘表 1 也问“过程中有没有痛点”，位于标为 describe 的栏内。", "quote_en": "Which steps of the process are most important to them? Were there pain points along the way?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p43-high-low-lines": {"claim_id": "im.impro-p43-high-low-lines", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在《Impro》里把高地位和低地位各写成一句潜台词：演高地位的人是在说「别靠近我，我咬人」，演低地位的人是在说「别咬我，我不值得你费劲」。", "quote_en": "A person who plays high status is saying 'Don't come near me, I bite.' Someone who plays low status is saying 'Don't bite me, I'm not worth the trouble.'", "quote_zh": "演高地位的人是在说：“别靠近我，我会咬人。”演低地位的人是在说：“别咬我，我不值得你费劲。”", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 43", "review_state": "checked"}, "im.impro-p43-preferred-hedge": {"claim_id": "im.impro-p43-preferred-hedge", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 自己把「人有偏好的地位，并会设法挪向偏好的位置」这个论断标成当下的看法：开头写的是 My belief (at this moment)。", "quote_en": "My belief (at this moment) is that people have a preferred status; that they like to be low, or high, and that they try to manoeuvre themselves into the preferred positions.", "quote_zh": "我（此刻）的看法是，人有自己偏爱的地位：他们喜欢低，或者喜欢高，并且会设法让自己挪到偏爱的位置上。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 43", "review_state": "checked"}, "im.impro-p43-status-specialist": {"claim_id": "im.impro-p43-status-specialist", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 说，所演的地位是一种有效的防御，人会越来越被这种防御定型，成为只擅长一种地位的「status specialist」，被要求演相反地位时会觉得没有防护。", "quote_en": "You become a status specialist, very good at playing one status, but not very happy or competent at playing the other.", "quote_zh": "你成了一个地位专才，很擅长演一种地位，演另一种时却不太自在，也不太胜任。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 43", "review_state": "checked"}, "im.impro-p42-experience-before-term": {"claim_id": "im.impro-p42-experience-before-term", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 教学时先让学生体验各种地位感觉，之后才讨论含义甚至引入「status」这个词，用这种次序减少学生对地位概念的抵触。", "quote_en": "I minimise 'status resistance' from my students by getting them to experience various status sensations before I discuss the implications, or even introduce the term.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p43-head-still": {"claim_id": "im.impro-p43-head-still", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在课上做了一个演示：说话时保持头部不动，然后告诉学生这会明显改变自己对自己的感受和别人对他的感受。", "quote_en": "Finally I explain that I'm keeping my head still whenever I speak, and that this produces great changes in the way I perceive myself and am perceived by others.", "quote_zh": "最后我解释说，我每次说话都让头保持不动，这会大大改变我怎么看自己，也大大改变别人怎么看我。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 43", "review_state": "checked"}, "im.impro-p43-head-role": {"claim_id": "im.impro-p43-head-role", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 写到需要权威的角色（悲剧英雄之类）要学会头部不动：演掘墓人可以边说边晃头，演哈姆雷特不行。", "quote_en": "Actors needing authority—tragic heroes and so on—have to learn this still head trick. You can talk and waggle your head about if you play the gravedigger, but not if you play Hamlet.", "quote_zh": "需要权威的演员——悲剧英雄之类——得学会这个头不动的诀窍。演掘墓人，你可以边说边晃脑袋；演哈姆雷特就不行。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 43", "review_state": "checked"}, "im.impro-p44-chain-effects": {"claim_id": "im.impro-p44-chain-effects", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 称，他说话时若保持头部不动，就会自动做出许多别的高地位行为：说完整的句子、保持眼神接触、动作更流畅、占更多「空间」。", "quote_en": "If I speak with a still head, then I'll do many other high-status things quite automatically. I'll speak in complete sentences, I'll hold eye contact.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p44-above-below-partner": {"claim_id": "im.impro-p44-above-below-partner", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 规定练习中学生的地位只能比搭档高一点或低一点，这样学生必须真正看着搭档，并按对方的行为来调整自己的行为。", "quote_en": "I insist that they have to get their status just a little above or below their partner's. This ensures that they really 'see' their partner …", "quote_zh": "我坚持要他们把自己的地位定得只比搭档高一点或低一点。这样能确保他们真正“看见”搭档……", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 44", "review_state": "checked"}, "im.impro-p44-lock-on": {"claim_id": "im.impro-p44-lock-on", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 说，地位练习一旦让地位技能变成自动反应，它们就会「锁定」对手演员，学生随即变得善于观察，看上去像经验丰富的即兴演员。", "quote_en": "The automatic status skills then 'lock on to' the other actor, and the students are transformed into observant, and apparently very experienced improvisers.", "quote_zh": "这时，自动起作用的地位技巧会“锁定”对方演员，学生们也就变成了善于观察、看上去经验十足的即兴演员。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 44", "review_state": "checked"}, "im.impro-p44-real-life-adjust": {"claim_id": "im.impro-p44-real-life-adjust", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 认为这些地位练习在舞台上重现了现实生活的效果：每个人每时每刻都在把自己的地位向上或向下调整一点点。", "quote_en": "These status exercises reproduce on the stage exactly the effects of real life, in which moment by moment each person adjusts his status up or down a fraction.", "quote_zh": "这些地位练习在舞台上原样再现了现实生活的效果：在现实中，每个人时时刻刻都在把自己的地位往上或往下调一点点。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 44", "review_state": "checked"}, "im.impro-p42-perception-difficulty": {"claim_id": "im.impro-p42-perception-difficulty", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 自己承认，不同报告对眼神接触与支配的结论互相矛盾，他据此说明实际察觉地位交易是困难的。", "quote_en": "Such disagreements indicate the difficulty of actually perceiving status transactions.", "quote_zh": "这类分歧表明，要真正察觉地位交易是困难的。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 42", "review_state": "checked"}, "im.impro-p46-crutches": {"claim_id": "im.impro-p46-crutches", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 把地位练习称为「拐杖」：它们托住演员，使本能系统得以运转，演员因此觉得一切很容易，也不觉得自己在「表演」。", "quote_en": "The status exercises are really crutches to support the actor so that instinctual systems can operate.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p46-no-preparation": {"claim_id": "im.impro-p46-no-preparation", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 称，地位一旦像生活中那样变成自动反应，就能在完全没有准备的情况下即兴演出复杂的场景。", "quote_en": "Once the status becomes automatic, as it is in life, it's possible to improvise complex scenes with no preparation at all.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p46-theatre-machine": {"claim_id": "im.impro-p46-theatre-machine", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 写道，没有地位训练，他的即兴剧团 Theatre Machine 不可能在欧洲成功巡演，因为那样就得先排练场景。", "quote_en": "Without the status work my improvisation group, the Theatre Machine, could never have toured successfully in Europe; not without preparing the scenes first.", "quote_zh": "没有地位训练，我的即兴剧团 Theatre Machine 绝不可能在欧洲巡演成功；除非事先把场景排好。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 46", "review_state": "checked"}, "im.impro-p46-answers-automatic": {"claim_id": "im.impro-p46-answers-automatic", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 用一个「地狱」场景说明：被问到「Excrement」这类突如其来的台词时，知道自己演的是哪种地位，答案就会自动出来，不需要「想」。", "quote_en": "If you know what status you're playing the answers come automatically.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.impro-p50-smith-sir": {"claim_id": "im.impro-p50-smith-sir", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 的「Smith 与 Sir」解雇场景里，如果 Smith 演高地位，说出「Won't you reconsider」就给了他一个巨大的对抗阻力，Sir 说再见时场面因此扣人心弦。", "quote_en": "If Smith plays high, then saying 'Won't you reconsider' gives him an enormous resistance to work against.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.impro-p50-objects": {"claim_id": "im.impro-p50-objects", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 称地位不仅演给人，也演给物：进入空的候诊室时可以对家具演高或低的地位，他还让等着搭档上场的演员「对长椅演低地位」。", "quote_en": "Status is played to anything, objects as well as people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p55-resistance-safety": {"claim_id": "im.impro-p55-resistance-safety", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 指出教地位互动时，学生有意识上愿意，潜意识里可能有很强的抵触，所以必须让学生觉得安全并对教师有信心。", "quote_en": "… however willing the student is consciously, there may be very strong subconscious resistances. Making the student safe, and getting him to have confidence in you, are essential.", "quote_zh": "……无论学生在意识上多么愿意，潜意识里都可能有很强的抵触。让学生感到安全，让他对你有信心，是必不可少的。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 55", "review_state": "checked"}, "im.impro-p55-56-cast-to-type": {"claim_id": "im.impro-p55-56-cast-to-type", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在讲「status specialist」时写道：糟糕的戏剧学校会按类型选角，让人一直演自己偏好的地位，只利用已有的本事，不拓宽范围。这是他书中 cast 一词与地位相连的地方。", "quote_en": "In a bad drama school it's possible to play your 'preferred' status all the time, since they cast you to type, exploiting what you can do, instead of widening your range.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p56-specialists": {"claim_id": "im.impro-p56-specialists", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 认为职业剧场里的演员大致分成高地位专才和低地位专才，并主张合格的演员训练应当教会所有类型的地位交易。", "quote_en": "A proper training for actors would teach all types of transaction.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p33-continuous": {"claim_id": "im.impro-p33-continuous", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在 Status 一章开头写道，地位交易在现实中一直持续，不只发生在冲突时；他用公园里鸭子冲突之外也小心保持距离作类比。", "quote_en": "In reality status transactions continue all the time.", "quote_zh": "在现实中，地位交易一直都在进行。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 33", "review_state": "checked"}, "im.impro-p37-friends": {"claim_id": "im.impro-p37-friends", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 对「朋友之间不玩地位」这一反驳的回答是：熟人变成朋友，是因为双方同意一起玩地位游戏。", "quote_en": "My answer is that acquaintances become friends when they agree to play status games together.", "quote_zh": "我的回答是：熟人同意一起玩地位游戏的时候，就成了朋友。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 37", "review_state": "checked"}, "im.impro-p35-competitive-cooperative": {"claim_id": "im.impro-p35-competitive-cooperative", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 设想，如果教师把地位交易当作游戏来教，团体的气氛会变好，一个竞争型的团体可能转为合作型。", "quote_en": "the group might have flipped over from acting as a competitive group into acting as a co-operative one", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.impro-p36-something-one-does": {"claim_id": "im.impro-p36-something-one-does", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 把地位定义为一种做出来的行为，而不是社会身份：社会地位低的人可以演高地位，反之亦然，他随后用流浪汉与公爵夫人的对话举例。", "quote_en": "… something one does. You may be low in social status, but play high, and vice versa.", "quote_zh": "……一个人所做的事。你的社会地位可能低，却演高地位，反过来也一样。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 36", "review_state": "checked"}, "im.impro-p39-comedian": {"claim_id": "im.impro-p39-comedian", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 写道，喜剧演员是被人付钱来降低自己或别人地位的人。", "quote_en": "A comedian is someone paid to lower his own or other people's status.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p72-world-differently": {"claim_id": "im.impro-p72-world-differently", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 称地位交易不只对即兴演员有意义：一旦懂得每个声音和姿势都暗示一种地位，人看世界的方式会变，而且这种改变大概是永久的。", "quote_en": "Once you understand that every sound and posture implies a status, then you perceive the world quite differently, and the change is probably permanent.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p32-accept-blame": {"claim_id": "im.impro-p32-accept-blame", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 教学时先承担失败的责任，再要求学生用能学得最快的方式安排自己；他在书里说自己教的是 spontaneity。", "quote_en": "In exchange for accepting the blame for failure, I ask the students to set themselves up in such a way that they'll learn as quickly as possible.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p92-yes-no-sayers": {"claim_id": "im.impro-p92-yes-no-sayers", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 把人分成偏好说 Yes 与偏好说 No 的两类，写道说 No 的人多得多，但可以训练一类人表现得像另一类；这句话前半（Yes 换来冒险，No 换来安全）与 2016 年 TEDx 的标题卡相同。", "quote_en": "There are far more 'No' sayers around than 'Yes' sayers, but you can train one type to behave like the other.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.impro-p94-blocking-aggression": {"claim_id": "im.impro-p94-blocking-aggression", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在「Blocking and Accepting」一节写道：阻挡是一种攻击。理由是他让两个学生互说「我爱你」时，学生几乎总是接受对方的想法。", "quote_en": "Blocking is a form of aggression. I say this because if I set up a scene in which two students are to say 'I love you' to each other, they almost always accept each other's ideas.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p95-prefer-block": {"claim_id": "im.impro-p95-prefer-block", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 观察到有些学生偏好让步（他称这些人是「迷人」的人），多数学生则偏好阻挡，而且往往没意识到自己在阻挡。", "quote_en": "Some students prefer to yield (these are 'charming' people) but most prefer to block, even though they may have no idea …", "quote_zh": "有些学生喜欢让步（这些是“讨人喜欢”的人），但大多数学生喜欢阻挡，尽管他们可能并不知道……", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 95", "review_state": "checked"}, "im.impro-p97-programme": {"claim_id": "im.impro-p97-programme", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 的做法是给两个演员设定程序：A 提出并接受，B 提出并阻挡，借此训练和观察 offer、block、accept 三种动作。", "quote_en": "You can programme two actors so that A offers and accepts, and B offers and blocks.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p99-accept-all-offers": {"claim_id": "im.impro-p99-accept-all-offers", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 在 1979 年的书里写，出色的即兴演员看上去像心灵感应、一切像事先安排好，原因是他们接受对方给出的所有 offer，而这是「正常」人不会做的事。", "quote_en": "… everything looks prearranged. This is because they accept all offers made—which is something no 'normal' person would do. Also they may accept offers which weren't really intended.", "quote_zh": "……一切看上去都像事先安排好的。这是因为他们接受对方给出的所有提议——这是任何“正常”人都不会做的事。他们还可能接受对方其实并非有意给出的提议。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 99", "review_state": "checked"}, "im.impro-p99-assume-offer": {"claim_id": "im.impro-p99-assume-offer", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 要求演员不要去想一个 offer，而要假定对方已经给出了一个。", "quote_en": "I tell my actors never to think up an offer, but instead to assume that one has already been made.", "quote_zh": "我告诉我的演员，永远不要去构想提议，而要假定对方已经给出了一个。", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 99", "review_state": "checked"}, "im.impro-p100-accidents": {"claim_id": "im.impro-p100-accidents", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 称学会接受 offer 之后，意外就不能再打断表演；他举了斯坦尼斯拉夫斯基责备椅子塌了的演员没有继续演的例子。", "quote_en": "Once you learn to accept offers, then accidents can no longer interrupt the action.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.impro-p101-rain-example": {"claim_id": "im.impro-p101-rain-example", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "Johnstone 用一个例子说明新手为何受挫：新手伸出手试探是否下雨，搭档却握住他的手说「幸会」，新手便生气。", "quote_en": "An inexperienced improviser gets annoyed because his partners misunderstand him. He holds out his hand to see if it's raining, and his partner shakes it and says 'Pleased to meet you.'", "quote_zh": "缺乏经验的即兴演员会恼火，因为搭档误解了他。他伸出手想试试是不是下雨了，搭档却握住他的手说：“幸会。”", "screen_locator": "Keith Johnstone, Impro, Routledge 2012, p. 101", "review_state": "checked"}, "im.impro-p103-yes-but-yes-and": {"claim_id": "im.impro-p103-yes-but-yes-and", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "在《Impro》里，「Yes, But」是一个众所周知的 accept-and-block 游戏，出自 Viola Spolin；其孪生游戏「Yes, and」是 accept-and-offer 游戏。书里把它们当作练习游戏，而不是通用规则。", "quote_en": "This is a well known 'accept-and-block' game (described in Viola Spolin, Improvisation for the Theatre). (Its twin game 'Yes, and ...' is an 'accept-and-offer' game", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.blog-inspires-partner": {"claim_id": "im.blog-inspires-partner", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 在自己的博客里写，他指导即兴时想给演员能启发他们的想法，并以「好点子就是能启发搭档的点子」为准。", "quote_en": "I want to give the players ideas that inspire them. ('A good idea is one that inspires your partner!)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.blog-accept-without-cheering": {"claim_id": "im.blog-accept-without-cheering", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 写道，如果演员接受了他的建议却没有真正高兴起来，他会质疑，再提别的建议，直到他们真的高兴为止；他只要接受而不要敷衍。", "quote_en": "If they accept a suggestion without cheering up, I'll challenge them", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.blog-voting-winners-losers": {"claim_id": "im.blog-voting-winners-losers", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 回忆 Loose Moose 的一次会议：他不用投票做决定，理由是投票会产生赢家和输家。", "quote_en": "Voting creates winners and losers, so I avoid it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.blog-suggest-something-else": {"claim_id": "im.blog-suggest-something-else", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 写道，他知道 Loose Moose 想去的方向，但抵达的方式无穷多，所以提的想法若不能让对方感兴趣，他就再提别的，直到对方说「好，做吧」。", "quote_en": "if I suggest an idea that doesn’t interest you, I’ll suggest something else", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.blog-lights-submissive": {"claim_id": "im.blog-lights-submissive", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 用地位的语言讲舞台团队：灯光和音响即兴者若被要求完美，就会对演员处于从属地位，只把自己看作伴奏，而不是创作上的平等者。", "quote_en": "If the Lighting and Sound improvisers and the stage-management are expected to be perfect they'll be submissive to the improvisers.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.blog-partner-work-laughs": {"claim_id": "im.blog-partner-work-laughs", "unit": "im", "source_id": "im:johnstone-blog-theatre", "claim_type": "direct-source", "statement_zh": "Johnstone 批评一部讲 Second City 的书里的例子：一个演员接了搭档的道具却回答「我看你把窨井盖带来了」，得到笑声，但制造了敌意；他的建议是不要靠搞坏搭档配合来取笑。", "quote_en": "Don't get laughs by screwing up your partner work", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.straight-2007-perversion": {"claim_id": "im.straight-2007-perversion", "unit": "im", "source_id": "im:straight-2007", "claim_type": "eyewitness", "statement_zh": "2007 年 Johnstone 在电话采访中把「接受所有 offer」这条即兴规则称为「perversion」，说他觉得这很糟，即兴已经出了些坏事。", "quote_en": "… perversion. I think it's terrible. Bad things have happened to improvisation.", "quote_zh": "……扭曲。我觉得这很糟。即兴已经出了些坏事。", "screen_locator": "Guy MacPherson, Georgia Straight, 2007", "review_state": "checked"}, "im.guardian-ravenhill-detail": {"claim_id": "im.guardian-ravenhill-detail", "unit": "im", "source_id": "im:guardian-ravenhill-2009", "claim_type": "eyewitness", "statement_zh": "2009 年参加 Johnstone 一周工作坊的剧作家 Mark Ravenhill 报告说，Johnstone 对细节要求很严，常在练习开始几秒后就叫停。", "quote_en": "Johnstone is strong on detail, frequently stopping an exercise mere seconds after it's begun.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.globe-floor-sitting": {"claim_id": "im.globe-floor-sitting", "unit": "im", "source_id": "im:globe-obit-2023", "claim_type": "eyewitness", "statement_zh": "据学生 Mark McKinney 回忆，Johnstone 开课时坐在地上以示自己地位较低，并说他会为学生场景里的一切负责、学年中再把责任交还给他们，随后逐步抬高自己的地位。", "quote_en": "“I’m going to take responsibility for whatever you do in your scenes. And I’m going to hand you back that responsibility in the course of the year.”", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "im.qureshi-booklist": {"claim_id": "im.qureshi-booklist", "unit": "im", "source_id": "im:qureshi-2024", "claim_type": "eyewitness", "statement_zh": "Qureshi 说他入职时公司给新人寄了《Impro》、《The Looming Tower》、《Interviewing Users》和《Getting Things Done》，另给了后来成为 Dalio《Principles》的早期 PDF，并说他不确定公司现在是否还这样做。", "quote_en": "at the time when you joined they sent you a copy of Impro, The Looming Tower (9/11 book), Interviewing Users, and Getting Things Done.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.qureshi-why-impro": {"claim_id": "im.qureshi-why-impro", "unit": "im", "source_id": "im:qureshi-2024", "claim_type": "eyewitness", "statement_zh": "Qureshi 给出的理由是：做 FDE 要对社会语境异常敏感，要在最高层与客户或政府对口方结成伙伴并赢得信任，这常需要玩政治游戏；他说《Impro》受书呆子欢迎，部分因为它把社会行为拆成机制。", "quote_en": "Impro is popular with nerds partly because it breaks down social behavior mechanistically.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.qureshi-casting": {"claim_id": "im.qureshi-casting", "unit": "im", "source_id": "im:qureshi-2024", "claim_type": "eyewitness", "statement_zh": "Qureshi 说公司词汇里充满《Impro》的用语，并举「casting」为例，但没有解释它在公司里的含义。", "quote_en": "The vocabulary of the company was saturated with Impro-isms – ‘casting’ is an example.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.qureshi-hands-head-examples": {"claim_id": "im.qureshi-hands-head-examples", "unit": "im", "source_id": "im:qureshi-2024", "claim_type": "unresolved", "statement_zh": "Qureshi 转述 Johnstone 的身体例子：说话时头不动是高地位、头左右乱动是低地位、站直露出双手是高地位、驼背手插口袋是低地位。书中查到了头不动（p.43）和演哈姆雷特与掘墓人的对照，没有查到露手与插口袋这一组。", "quote_en": "… keeping your head still while talking is high status, whereas moving your head side to side a lot is low status. Standing tall with your hands showing is high status, slouching with your hands in your pocket is low status.", "quote_zh": "……说话时头不动是高地位，头左右乱晃是低地位。站得笔直、露出双手是高地位；弓着背、手插在口袋里是低地位。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "im.video-dvd-status-transactions": {"claim_id": "im.video-dvd-status-transactions", "unit": "im", "source_id": "im:keithjohnstone-site", "claim_type": "direct-source", "statement_zh": "Johnstone 官方网站介绍 DVD《Impro: Transformations》：他在其中教授地位交易、讲故事、自发性等内容，大部分拍摄于 2008 年卡尔加里的 Keith Johnstone 暑期学校，片长 105 分钟，有五种语言字幕。", "quote_en": "In the DVD ‘Impro: transformations’, Keith Johnstone teaches status transactions, storytelling, spontaneity and more, most of which was filmed at the 2008 Keith Johnstone Summer School in Calgary, Alberta, Canada.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.video-totino-master-servant": {"claim_id": "im.video-totino-master-servant", "unit": "im", "source_id": "im:yt-totino-master-servant", "claim_type": "direct-source", "statement_zh": "Frank Totino 在 YouTube 上传了 DVD 的节选《Keith Johnstone Teaches: Master-Servant Scene》（5:32，2011-03-10），拍摄于 2008 年卡尔加里的大师班，有多种语言字幕；本次没有取得字幕或文字稿，无法转述视频里的具体话。", "quote_en": "Excerpt from \"Keith Johnstone Teaches: Impro\" Shot in 2008, at Keith's Master Class in Calgary, Canada", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.video-suggestibles-status": {"claim_id": "im.video-suggestibles-status", "unit": "im", "source_id": "im:yt-suggestibles-status", "claim_type": "direct-source", "statement_zh": "Bev Fox 在 2008 年采访了 Johnstone，分六段短片，其中一段谈 Status（YouTube 1:48，2013-03-12 上传）；没有取得文字稿，不能引用其中的话。", "quote_en": "he talks about Fear and Risk, Spontaneity, Status, Mask, Comedy, and Teaching. Interviewed by Bev Fox in 2008.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.video-theatremuseum-yes-and": {"claim_id": "im.video-theatremuseum-yes-and", "unit": "im", "source_id": "im:yt-theatremuseum-yes-and", "claim_type": "direct-source", "statement_zh": "加拿大剧院博物馆的 20 段 Johnstone 访谈（Rebecca Northan 访问，2017-08-06，多伦多）第 18 段谈他对「总是说 Yes, and」这条规则的看法；内容未读到。", "quote_en": "Keith Johnstone discusses his thoughts on the commonly known improv rule to always say \"Yes, and...\"", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.video-tedxyyc": {"claim_id": "im.video-tedxyyc", "unit": "im", "source_id": "im:yt-tedxyyc", "claim_type": "direct-source", "statement_zh": "2016-09-12 TEDx Talks 发布 Johnstone 的 TEDxYYC 演讲《Don’t Do Your Best》（12:27）；演讲文字未取得。", "quote_en": "How to lead an improvised life by the inventor of Theatresports and world renowned improvisational theatre instructor, Keith Johnstone", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.iti-origin-spontaneous": {"claim_id": "im.iti-origin-spontaneous", "unit": "im", "source_id": "im:iti-about", "claim_type": "direct-source", "statement_zh": "国际 Theatresports 协会的 Johnstone 简介称，他在皇家宫廷剧院期间开始探索如何让演员更自发、更有反应、更有生气。", "quote_en": "With actors he began to explore how to make them more spontaneous, responsive and alive in their work.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.bloomsbury-sections": {"claim_id": "im.bloomsbury-sections", "unit": "im", "source_id": "im:bloomsbury-page-2022", "claim_type": "direct-source", "statement_zh": "Bloomsbury 出版方页面称《Impro》分四部分：Status、Spontaneity、Narrative Skills、Masks and Trance，并说这个顺序大致是一个小组接触它们的顺序。", "quote_en": "Divided into four sections, 'Status', 'Spontaneity', 'Narrative Skills' and 'Masks and Trance'", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.toc-routledge-pages": {"claim_id": "im.toc-routledge-pages", "unit": "im", "source_id": "im:gbooks-listing-2012", "claim_type": "direct-source", "statement_zh": "Routledge 2012 年版目录给出页码：Notes on Myself 13、Status 33、Spontaneity 75、Narrative Skills 109、Masks and Trance 143、Appendix 206；Status 一章约 42 页（33 至 74），约占全书 208 页的五分之一。", "quote_en": "Status 33 Spontaneity 75 Narrative Skills 109 Masks and Trance 143 Appendix 206", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.site-methuen-1979": {"claim_id": "im.site-methuen-1979", "unit": "im", "source_id": "im:keithjohnstone-site", "claim_type": "direct-source", "statement_zh": "Johnstone 官方网站把《Impro》的首版标为 1979 年伦敦 Methuen（ISBN 0-413-46430-X）；维基百科的信息框则写 Faber and Faber、1979，两者不一致。", "quote_en": "IMPRO: Improvisation and the Theatre©1979, Methuen Publishing, London ISBN 0-413-46430-X", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.buteau-misquote": {"claim_id": "im.buteau-misquote", "unit": "im", "source_id": "im:buteau-lessons", "claim_type": "inference", "statement_zh": "网上流传的《Impro》语录有改写：Buteau 的清单写成「Don’t touch me / Don’t hurt me」，与书中 p.43 的「Don't come near me, I bite / Don't bite me, I'm not worth the trouble」不同，且都没有页码。", "quote_en": "Playing high status is saying 'Don't touch me.' Playing low status is saying 'Don't hurt me.'", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.alberta-views-misdates-ravenhill": {"claim_id": "im.alberta-views-misdates-ravenhill", "unit": "im", "source_id": "im:albertaviews-2023", "claim_type": "inference", "statement_zh": "Alberta Views 把 Ravenhill 的 Johnstone 工作坊写成 2017 年伦敦，但他的 Guardian 文章发表于 2009-03-02，所以 Alberta Views 的年份有误。", "quote_en": "partook in a workshop with the man himself in London in 2017", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "im.commentary-cult-reading": {"claim_id": "im.commentary-cult-reading", "unit": "im", "source_id": "im:palantir-impro-commentary", "claim_type": "inference", "statement_zh": "网上评论对 Palantir 为何发《Impro》的解释（如「决定了这是怎样的一种教派」）是评论者自己的推理，不是 Palantir 内部人的证词。", "quote_en": "it makes total sense to assign Impro as mandatory reading for new Palantir hires.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.2001-two-objectives": {"claim_id": "gtd.2001-two-objectives", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版第 1 章开头（A New Practice for a New Reality）把方法归结为两个目标，第一个是把需要做的一切（现在、以后、将来也许，大事小事）收进一个脑外、心外的、合乎逻辑且可信的系统。", "quote_en": "a logical and trusted system outside of your head and off your mind", "quote_zh": "一个合乎逻辑、信得过的系统，放在你的脑子之外，也不再挂在你心上", "screen_locator": "David Allen, Getting Things Done, 2001, 第 1 章", "review_state": "checked"}, "gtd.2001-front-end-decisions": {"claim_id": "gtd.2001-front-end-decisions", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版的第二个目标是自律地对放进生活的每一个输入先做决定，使自己随时有一套可以执行或重新协商的下一步行动方案。", "quote_en": "front-end decisions about all of the “inputs” you let into your life", "quote_zh": "对你放进生活里的所有“输入”，预先做出决定", "screen_locator": "David Allen, Getting Things Done, 2001, 第 1 章", "review_state": "checked"}, "gtd.2001-toc-stages": {"claim_id": "gtd.2001-toc-stages", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版目录中，第 2 章名为五个阶段（The Five Stages of Mastering Workflow），第 5 至 9 章依次名为 Collection、Processing、Organizing、Reviewing、Doing；这些章的正文均未读到。", "quote_en": "Chapter 8 - Reviewing: Keeping Your System Functional", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.2001-toc-next-action": {"claim_id": "gtd.2001-toc-next-action", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版第 11、12、13 章分别是收集习惯、下一步行动决定、结果聚焦的力量，可见作者把下一步行动决定当作与收集并列的核心原则；这三章正文未读。", "quote_en": "Chapter 12 - The Power of the Next-Action Decision", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.2001-excerpt-ends": {"claim_id": "gtd.2001-excerpt-ends", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "unresolved", "statement_zh": "官方节选在第 1 章小节标题处截止（第 143 行），全文没有出现两分钟字样，所以 2001 版正文是否写了两分钟规则无法核实。", "quote_en": "The Old Models and Habits Are Insufficient", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.2001-no-single-solution": {"claim_id": "gtd.2001-no-single-solution", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版引言里作者自述：二十多年之后他仍认为不存在一劳永逸的单一解法，软件、研讨会、个人规划本或个人使命宣言都不能替人做选择。", "quote_en": "there is no single, once-and-for-all solution", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.2001-habits-must-change": {"claim_id": "gtd.2001-habits-must-change", "unit": "gtd", "source_id": "gtd:S-2001-EXCERPT", "claim_type": "direct-source", "statement_zh": "2001 版第 1 章开头作者承认，多数人要先改掉一些主要的工作习惯，才能实施这套系统。", "quote_en": "some major work habits that must be modified before they can implement this system", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.site-2026-names-capture": {"claim_id": "gtd.site-2026-names-capture", "unit": "gtd", "source_id": "gtd:S-DAC-WHATISGTD-2026", "claim_type": "direct-source", "statement_zh": "公司官网现行页面（页面元数据：2019-04-19 发布、2024-07-02 修改）把方法写成五步 Capture、Clarify、Organize、Reflect、Engage；Capture 是把引起注意的一切写下、录下或收进一个收集工具。", "quote_en": "any and everything that has your attention into a collection tool", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.site-2026-clarify": {"claim_id": "gtd.site-2026-clarify", "unit": "gtd", "source_id": "gtd:S-DAC-WHATISGTD-2026", "claim_type": "direct-source", "statement_zh": "现行官网对 Clarify 的写法是：问是否可行动；可行动就决定下一步行动，需要多于一个动作时再决定项目；不可行动就判断是垃圾、参考资料还是搁置。", "quote_en": "decide the next action and project (if more than one action is required)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.site-2026-reflect": {"claim_id": "gtd.site-2026-reflect", "unit": "gtd", "source_id": "gtd:S-DAC-WHATISGTD-2026", "claim_type": "direct-source", "statement_zh": "现行官网把第四步 Reflect 写成频繁回顾：更新并检视系统内所有相关内容，以恢复掌控和专注。", "quote_en": "Update and review all pertinent system contents to regain control and focus", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.site-2026-engage": {"claim_id": "gtd.site-2026-engage", "unit": "gtd", "source_id": "gtd:S-DAC-WHATISGTD-2026", "claim_type": "direct-source", "statement_zh": "现行官网把第五步 Engage 写成：用可信系统带着信心和清晰度做行动决定。", "quote_en": "Use your trusted system to make action decisions with confidence and clarity", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.wb2014-labels": {"claim_id": "gtd.wb2014-labels", "unit": "gtd", "source_id": "gtd:S-DAC-FIVESTEPS-WB-2014", "claim_type": "direct-source", "statement_zh": "2015 年 3 月修订版出版前，公司官网五步页的 2014-05-31 存档已经用 Capture、Clarify、Organize、Reflect、Engage 作标签，并把 Collect what has your attention、Process what it means、Review frequently、Simply do 留作副标题。", "quote_en": "PROCESS WHAT IT MEANS", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.wb2014-clarify-body": {"claim_id": "gtd.wb2014-clarify-body", "unit": "gtd", "source_id": "gtd:S-DAC-FIVESTEPS-WB-2014", "claim_type": "direct-source", "statement_zh": "2014-05-31 存档的 Clarify 说明里，先问能否行动，能就决定最近的下一步行动，若不到两分钟就当场做，否则能委派就委派，或放进下一步行动清单。", "quote_en": "If it will take less than two minutes, do it now.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.summary-drift-2019": {"claim_id": "gtd.summary-drift-2019", "unit": "gtd", "source_id": "gtd:S-DAC-WHATISGTD-WB-2019", "claim_type": "direct-source", "statement_zh": "官网对 Clarify 的一句话概述随时间在变：2014 年含两分钟条款；2019-06-16 存档写作可行动则 do it now、delegate it 或 defer it，没有两分钟字样；2026 年现行页改为决定下一步行动和项目，既无两分钟也无 do/delegate/defer。", "quote_en": "If it is, do it now, delegate it or defer it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.post-2012-old-terms": {"claim_id": "gtd.post-2012-old-terms", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2012-5PHASES", "claim_type": "direct-source", "statement_zh": "公司 2012 年的文章仍把工作流写成五个阶段：Collect、Process、Organize、Review、Do。", "quote_en": "There are five phases of your workflow: Collect, Process, Organize, Review & Do.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.staff-comment-vocabulary": {"claim_id": "gtd.staff-comment-vocabulary", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2015-UPDATED", "claim_type": "direct-source", "statement_zh": "公司员工 2018-01-29 在 2015 年新版文章下回复，转述 Allen 的话：新版在组成部分的用词和描述上有一些细微改动，理由是他多年来对 GTD 应用的细微之处理解更深。", "quote_en": "some subtle changes in the vocabulary and descriptions of the components", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.staff-comment-method-unchanged": {"claim_id": "gtd.staff-comment-method-unchanged", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2015-UPDATED", "claim_type": "direct-source", "statement_zh": "同一条员工回复转述 Allen：GTD 方法论没有改变，新版还加入了认知研究来佐证；回复没有列出具体改了哪些词。", "quote_en": "The GTD methodology hasn’t changed", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.about-2015-edition": {"claim_id": "gtd.about-2015-edition", "unit": "gtd", "source_id": "gtd:S-DAC-ABOUT", "claim_type": "direct-source", "statement_zh": "公司官网的大事记写明：2015 年出版第二版，称其被完全重写，并同时以 25 种语言发行。", "quote_en": "Completely rewritten and released in 25 languages.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "gtd.blurb-rewritten": {"claim_id": "gtd.blurb-rewritten", "unit": "gtd", "source_id": "gtd:S-DAC-BOOKS", "claim_type": "direct-source", "statement_zh": "出版方文案（同一段也挂在公司官网 Books 页）称作者把书从头到尾重写，并补充了关于新型工作场所的内容；这是营销文字，不是对书中改动的清单。", "quote_en": "Allen has rewritten the book from start to finish", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.ep01-principles-unchanged": {"claim_id": "gtd.ep01-principles-unchanged", "unit": "gtd", "source_id": "gtd:S-DAC-EP01", "claim_type": "direct-source", "statement_zh": "2015 年 5 月官方播客第 1 期里，被问到第二版是否有新原则，Allen 答：原则一点都没有变。", "quote_en": "No, the principles haven’t changed at all.", "quote_zh": "没有，原则一点都没变。", "screen_locator": "David Allen, GTD Podcast #1, 2015", "review_state": "checked"}, "gtd.ep01-inbasket-next-actions": {"claim_id": "gtd.ep01-inbasket-next-actions", "unit": "gtd", "source_id": "gtd:S-DAC-EP01", "claim_type": "direct-source", "statement_zh": "同一段回答里 Allen 说，哪怕到了 2190 年登陆木星，人仍然需要一个起收件箱作用的东西，也仍然要决定出现的事情的下一步行动。", "quote_en": "decide what are the next actions on things that show up", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.fer-tweaked-language": {"claim_id": "gtd.fer-tweaked-language", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "2019 年 Allen 对 Tim Ferriss 说，新版（他称两三年前出的）更新了不少内容，并明显调整了措辞。", "quote_en": "I’ve updated a bunch of stuff and tweaked the language-ing a good bit.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.fer-new-terms-spoken": {"claim_id": "gtd.fer-new-terms-spoken", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "2019 年访谈中 Allen 本人口述五步时用的是 capture、clarify、organize、reflect、engage，说明这套新词是作者自己的用语，不只是官网文案。", "quote_en": "capture, clarify, organize, reflect, and engage", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.version-split": {"claim_id": "gtd.version-split", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2015-UPDATED", "claim_type": "inference", "statement_zh": "可靠的 2001 用词与后来官方用词的对照，只能由四块材料拼出：2001 目录的章名、公司 2012 年的文章、2014 年存档的官网标签、作者 2015 与 2019 年的口述；它不是 2001 版与 2015 版正文的逐段对照，2015 版正文一字未读。", "quote_en": "some subtle changes in the vocabulary and descriptions of the components", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.head-no-time-sense": {"claim_id": "gtd.head-no-time-sense", "unit": "gtd", "source_id": "gtd:S-DAC-EP35", "claim_type": "direct-source", "statement_zh": "Allen 的机理说法是：留在脑子里的承诺没有过去和未来的概念，所以会在不合时宜的时刻（如凌晨）反复催你；这是他在演讲里的断言，未给出研究出处。", "quote_en": "it has no sense of past or future", "quote_zh": "它没有过去和将来的概念", "screen_locator": "David Allen, GTD Podcast #35, 2017", "review_state": "checked"}, "gtd.head-crappy-office": {"claim_id": "gtd.head-crappy-office", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 的一句话概括：多数人仍把脑袋当办公室用，而脑袋是糟糕的办公室。", "quote_en": "your head’s a crappy office", "quote_zh": "脑子是个很糟的办公室", "screen_locator": "David Allen, The Tim Ferriss Show #384, 2019", "review_state": "checked"}, "gtd.four-things-claim": {"claim_id": "gtd.four-things-claim", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 断言人的大脑没有进化到能同时记住、提醒、排序或管理四件以上事情之间的关系，并称这是新的认知科学数据；访谈里没有给出具体研究。", "quote_en": "remember, remind, prioritize, or manage relationships with more than four things", "quote_zh": "记住、提醒、排序，或者管理四件以上事情之间的关系", "screen_locator": "David Allen, The Tim Ferriss Show #384, 2019", "review_state": "checked"}, "gtd.false-control-hypothesis": {"claim_id": "gtd.false-control-hypothesis", "unit": "gtd", "source_id": "gtd:S-DAC-EP01", "claim_type": "direct-source", "statement_zh": "对于人们为何仍把事留在脑子里，Allen 在 2015 年给的解释是他自称的工作假设：这给人一种虚假的控制感。", "quote_en": "it gives people a false sense of control to keep it in your head", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.keep-agreement": {"claim_id": "gtd.keep-agreement", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 说对自己的未完成承诺有三条出路：不做这个承诺（含挪到 someday/maybe）、守约去做、重新协商；你不必把事做完才算守约，但必须把它从脑子里拿出来。", "quote_en": "you don’t have to finish the thing to keep your agreement", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.capture-hours": {"claim_id": "gtd.capture-hours", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 称据他的辅导经验，中高层专业人士光是把占据注意力的事收集出来就要一到六小时，这一步不整理、不排序、不做决定。", "quote_en": "it takes one to six hours, just to capture what has their attention", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.calendar-analogy": {"claim_id": "gtd.calendar-analogy", "unit": "gtd", "source_id": "gtd:S-DAC-EP01", "claim_type": "direct-source", "statement_zh": "Allen 用日历说明外脑原则：凡是记日历的人已经在应用这条原则，即把头脑记不住的东西放进某个系统，并养成到时去看的行为。", "quote_en": "Anybody who keeps a calendar is already doing that", "quote_zh": "凡是记日历的人，已经在这么做了", "screen_locator": "David Allen, GTD Podcast #1, 2015", "review_state": "checked"}, "gtd.mismatch-location-meaning": {"claim_id": "gtd.mismatch-location-meaning", "unit": "gtd", "source_id": "gtd:S-DAC-EP35", "claim_type": "direct-source", "statement_zh": "Allen 的另一种说法：东西所在的位置与它对你的意义不一致，就成为一个不必要的压力源；他让听众在钱包里找一件不该长期放在那里的东西来演示。", "quote_en": "where it is doesn’t match what the thing means to you", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.disorganization-definition": {"claim_id": "gtd.disorganization-definition", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2015-NAMING", "claim_type": "direct-source", "statement_zh": "Allen 在 2015 年的文章里把杂乱定义为东西所在的位置与它对你的意义之间的差距，并认为准确命名事物会减轻它对人的控制。", "quote_en": "a discrepancy between where something is and what it means to you", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "gtd.say-no-after-inventory": {"claim_id": "gtd.say-no-after-inventory", "unit": "gtd", "source_id": "gtd:S-DAC-EP35", "claim_type": "direct-source", "statement_zh": "Allen 认为不知道自己手上有多少项目时，只能凭诚信接下所有权威人士派来的项目；知道总数之后就不得不说不，问题在于清点库存，而不在于多一点诚信。", "quote_en": "It’s not about getting any more integrity, it’s about getting your inventory clear.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.clarify-define-work": {"claim_id": "gtd.clarify-define-work", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 引用德鲁克：知识工作者最大的任务是界定自己的工作，因为工作并不自明；收到邮件不会告诉你该怎么处理，要由你决定。", "quote_en": "your work is not self-evident", "quote_zh": "你的工作并不是一目了然的", "screen_locator": "David Allen, GTD Podcast #27, 2017", "review_state": "checked"}, "gtd.clarify-nonactionable-three": {"claim_id": "gtd.clarify-nonactionable-three", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 在 Clarify 这一步先问是否可行动；不可行动的东西分三类：垃圾、参考资料、暂时无法决定而需要搁置（incubate）的事。", "quote_en": "So those are three subcategories of non-actionable things", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.next-action-definition": {"claim_id": "gtd.next-action-definition", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 对下一步行动的定义很具体：如果你生活里除了完成这件事别无他事，你要采取的下一个物理的、看得见的动作是什么。", "quote_en": "What’s the next physical, visible action you would need to take", "quote_zh": "你需要采取的下一个具体的、看得见的动作是什么", "screen_locator": "David Allen, GTD Podcast #27, 2017", "review_state": "checked"}, "gtd.next-action-not-decided": {"claim_id": "gtd.next-action-not-decided", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 说大多数人写下的只是一件事，而没有写下下一步：还没确定做起来是什么样、在哪里做，也就是思考没有做完。", "quote_en": "You haven’t yet determined what doing looks like and where it happens.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.project-definition": {"claim_id": "gtd.project-definition", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 的项目定义很宽：凡是一个动作做不完的承诺都算项目，需要记入项目清单，写明结果。", "quote_en": "anything you can’t finish with one action step", "quote_zh": "凡是一个动作完成不了的事", "screen_locator": "David Allen, GTD Podcast #27, 2017", "review_state": "checked"}, "gtd.volume-next-actions": {"claim_id": "gtd.volume-next-actions", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 说他辅导的中高层专业人士手上一般有大约 150 到 220 条待办的下一步行动；他在 Ferriss 访谈里提到的项目数是 30 到 100，另一份讲义（Threefold Nature of Work）则说多数专业人士有 150 到 200 个具体动作。", "quote_en": "Most of you have about 150 to 220 of those.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.volume-projects": {"claim_id": "gtd.volume-projects", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 说中高层专业人士一般有 30 到 100 个项目，即一个动作做不完的承诺。", "quote_en": "between 30 and 100 of those projects", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.todo-incomplete": {"claim_id": "gtd.todo-incomplete", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2011-NEXTACTION", "claim_type": "direct-source", "statement_zh": "Allen 称他见过的待办清单有九成以上是仍不清楚事项的不完整清单；九成这个数是他的估计，没有给出样本。", "quote_en": "incomplete inventories of still-unclear things", "quote_zh": "一份份不完整的清单，列的是还没想清楚的事", "screen_locator": "David Allen, GTD Times, 2011", "review_state": "checked"}, "gtd.mom-example": {"claim_id": "gtd.mom-example", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2011-NEXTACTION", "claim_type": "direct-source", "statement_zh": "Allen 的标准例子：清单上的单词 Mom 是没有澄清的待办；把它改写成项目结果（为妈妈的生日办一次聚会），再写出明确的下一步行动（打电话问姐姐该怎么给妈妈过生日）。", "quote_en": "“Mom” is an unclarified to do item.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.zeroes-and-ones": {"claim_id": "gtd.zeroes-and-ones", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 把结果与行动称为生产力的零和一，说多数人没有为占据注意力的事确定结果和具体行动，并说回答这些问题需要思考而思考很难。", "quote_en": "outcome and action are the zeroes and ones of productivity", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.first-ed-diagram-node": {"claim_id": "gtd.first-ed-diagram-node", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-1STED-DIAGRAM", "claim_type": "direct-source", "statement_zh": "作者配套第一版有声书的工作流图（页脚版权 2008、文件日期 2012-02-02）里，在问完下一步行动是什么之后有一个节点：是否不到两分钟；是则当场做，否则委派或推迟。", "quote_en": "Will it take less than 2 minutes?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-spoken-2019": {"claim_id": "gtd.two-min-spoken-2019", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "2019 年访谈中 Allen 在讲完 Clarify 的提问后补了一句：能在两分钟内做完的就当场做完，这就是两分钟规则。", "quote_en": "anything you can do in two minutes, you should finish right then", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-condition-2020": {"claim_id": "gtd.two-min-condition-2020", "unit": "gtd", "source_id": "gtd:S-DAC-EP79", "claim_type": "direct-source", "statement_zh": "2020-05-29 的官方播客里 Allen 说：只要你本来就需要做这件事，且能在不到两分钟内做完，就当场做；他称这纯粹是效率因素，因为日后再看一遍、再回顾的时间会超过两分钟。", "quote_en": "if you need to do it at all then do it right then", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-rationale-handout": {"claim_id": "gtd.two-min-rationale-handout", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-EMAIL", "claim_type": "direct-source", "statement_zh": "作者的邮件讲义（文件日期 2016-10）给出两分钟规则的理由：把邮件读完、关掉、再打开重读，比第一次看到时就办完更费时；讲义同时设了前提，即这件事你终归要做。", "quote_en": "It takes longer to read it, close it, open it, and read it again", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-rationale-speech": {"claim_id": "gtd.two-min-rationale-speech", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 在演讲里把两分钟规则放在已经确定下一步行动之后：如果你终归要做且能在两分钟内做完，就当场做，因为追踪它再看一次比做完它更费时。", "quote_en": "it would take you longer to track it and look at it again", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-share-email": {"claim_id": "gtd.two-min-share-email", "unit": "gtd", "source_id": "gtd:S-DAC-EP27", "claim_type": "direct-source", "statement_zh": "Allen 称在邮件量大的环境里，三到四成需要行动的邮件能在两分钟内处理完；邮件讲义写的是至少三分之一。", "quote_en": "30-40% of your actionable e-mails are less than two minute turnaround", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.two-min-no-hard-rule": {"claim_id": "gtd.two-min-no-hard-rule", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2011-2MIN", "claim_type": "direct-source", "statement_zh": "2011 年读者问是否只有不到两分钟的事才该当场做，Allen 答：随时可以决定做耗时更长的事，没有硬性规定；如果想尽快清空收件箱并看到全部工作，就别在任何一条上花超过两分钟。", "quote_en": "No hard fast rules about any of that.", "quote_zh": "这些都没有硬性规定。", "screen_locator": "David Allen, GTD Times, 2011", "review_state": "checked"}, "gtd.weekly-review-cadence": {"claim_id": "gtd.weekly-review-cadence", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 说完整的做法是每周花一到两个小时回头整理并更新系统；他自己大约每七天做一次，常在隐约的焦虑冒头时做。", "quote_en": "take an hour or two, at least once a week", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.system-decays": {"claim_id": "gtd.system-decays", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 说不做每周回顾，系统就会过时，人会很快放弃这套做法。", "quote_en": "it gets out of date", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.weekly-review-checks-next-action": {"claim_id": "gtd.weekly-review-checks-next-action", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-WEEKLY", "claim_type": "direct-source", "statement_zh": "官方每周回顾清单（版本 2015-05-20）要求逐个检查项目与更大结果的清单，确保每个项目至少有一条当前的下一步行动。", "quote_en": "ensuring at least one current next action item", "quote_zh": "确保至少有一条当前的下一步行动", "screen_locator": "GTD Weekly Review Checklist, 2015", "review_state": "checked"}, "gtd.horizons-six": {"claim_id": "gtd.horizons-six", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-HORIZONS", "claim_type": "direct-source", "statement_zh": "作者的 Horizons of Focus 讲义（2016-10-05 版）称工作至少在六个高度上被界定和管理：目的与原则、愿景、目标、责任领域、项目，以及最底层的日历与下一步行动。", "quote_en": "at least six different horizons", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.horizons-top-down": {"claim_id": "gtd.horizons-top-down", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-HORIZONS", "claim_type": "direct-source", "statement_zh": "同一份讲义称优先级自上而下决定：目的与价值驱动愿景，愿景产生目标，目标框定责任领域，其下才是项目和动作。", "quote_en": "Priorities are determined from the top down", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.defining-work-hour": {"claim_id": "gtd.defining-work-hour", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-THREEFOLD", "claim_type": "direct-source", "statement_zh": "作者讲义称，处理新进输入、界定工作这件事平均每个典型专业人士每天要花一小时，这还只是保持当前，不含清理积压。", "quote_en": "requires an average of one hour per day, for the typical professional", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.limit-not-overnight": {"claim_id": "gtd.limit-not-overnight", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2015-OVERNIGHT", "claim_type": "direct-source", "statement_zh": "Allen 2015 年自己写道：GTD 不是一个一夜见效的时间管理小技巧，而是一门没有尽头的终身技艺。", "quote_en": "not an overnight little time-management tip and trick", "quote_zh": "不是一夜见效的时间管理小窍门", "screen_locator": "David Allen, GTD Times, 2015", "review_state": "checked"}, "gtd.limit-not-just-tools": {"claim_id": "gtd.limit-not-just-tools", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2010-WHATISGTD", "claim_type": "direct-source", "statement_zh": "公司官网的一篇介绍文章（2010 发布、2018 改过，措辞无法确定年份）说 GTD 不只是清空收件箱、选好工具或做每周回顾，并说唯一正确的做法是以最少的投入注意力把有意义的事做完。", "quote_en": "not just about inbox zero, picking great tools, or doing a Weekly Review", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.limit-no-problems-removed": {"claim_id": "gtd.limit-no-problems-removed", "unit": "gtd", "source_id": "gtd:S-DAC-EP17", "claim_type": "direct-source", "statement_zh": "2016 年的官方播客里 Allen 说实施一套好系统并不会消除生活中的挑战和问题，它只是把问题弄清楚，使你能与之协商。", "quote_en": "You don’t get rid of challenges and problems in your life", "quote_zh": "你不会就此摆脱生活里的挑战和问题", "screen_locator": "David Allen, GTD Podcast #17, 2016", "review_state": "checked"}, "gtd.limit-stress-free-yes-and-no": {"claim_id": "gtd.limit-stress-free-yes-and-no", "unit": "gtd", "source_id": "gtd:S-DAC-EP17", "claim_type": "direct-source", "statement_zh": "同一期里 Allen 承认无压力的生产力在字面上办不到：只要想做一件还没做的事，就已经制造了张力；他要的是让这种张力可以协商。", "quote_en": "you’ve created a dissonance or a kind of a stress or a tension", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.limit-no-abc-priority": {"claim_id": "gtd.limit-no-abc-priority", "unit": "gtd", "source_id": "gtd:S-DAC-EP17", "claim_type": "direct-source", "statement_zh": "同一期里，针对方法是否用 A、B、C 优先级码，Allen 答不用，理由是那对评估优先级来说过于简化；他说怎么排优先级不是简单的问题。", "quote_en": "too oversimplified a context for how to evaluate your priorities", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.limit-fall-off": {"claim_id": "gtd.limit-fall-off", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 承认人会在五步中的任何一步掉队：不把事写全、不决定下一步行动和结果、没有可信的整理系统、或不做每周回顾。", "quote_en": "people can fall off on any one of those", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.limit-rigidity-reply": {"claim_id": "gtd.limit-rigidity-reply", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "面对 GTD 太死板的质疑，Allen 的回答是只要刚好够用的结构，并用公路中线作类比；这是一个类比，不是证据。", "quote_en": "So just enough structure to give you the freedom.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.lonsdale-mention": {"claim_id": "gtd.lonsdale-mention", "unit": "gtd", "source_id": "gtd:S-LONSDALE-8VC", "claim_type": "direct-source", "statement_zh": "Lonsdale 在 8VC 的 Lessons from Peter Thiel 第 6 条里只有一句提到 GTD：在 GTD 里你不会把只要几分钟的任务往后拖。全文 GTD 只出现一次；该页面的开头是第三人称的介绍，页面元数据日期为 2010-04-11。", "quote_en": "you don’t put off tasks that only take a couple minutes", "quote_zh": "只要一两分钟的任务，你不会往后拖", "screen_locator": "Joe Lonsdale, Lessons from Peter Thiel, 8VC, 2010", "review_state": "checked"}, "gtd.lonsdale-vs-author": {"claim_id": "gtd.lonsdale-vs-author", "unit": "gtd", "source_id": "gtd:S-DAC-EP79", "claim_type": "inference", "statement_zh": "Lonsdale 的转述与作者自己的两分钟规则在要点上一致，但丢掉了作者的限定：规则用于已经确定下一步行动之后，且仅限你本来就要做的事，作者还说不是硬性规定；官方五步概述在 2019 年之后也已不含两分钟条款。", "quote_en": "if you need to do it at all then do it right then", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.naming-collision": {"claim_id": "gtd.naming-collision", "unit": "gtd", "source_id": "gtd:S-DAC-BLOG-2016-5STAGES", "claim_type": "direct-source", "statement_zh": "官方用法里五段这个说法指多个东西：2001 目录第 2 章是五个阶段，2012 年文章是五个阶段（phases），现行页面是五步（steps），而 2016 年的 The 5 Stages of GTD 讲的是掌握程度的 5 个 I，不是工作流。", "quote_en": "Where are you in the 5 I’s?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.wiki-plan-conflict": {"claim_id": "gtd.wiki-plan-conflict", "unit": "gtd", "source_id": "gtd:S-WIKI-GTD", "claim_type": "unresolved", "statement_zh": "维基百科说第一版五段是 collect、process、organize、plan、do；这与 2001 目录第 8 章名 Reviewing 以及公司 2012 年文章的 Review 不符，而 2001 第 2 章正文未读，所以这一点未解决，不能采用维基说法。", "quote_en": "collect, process, organize, plan, and do", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.ted-curacao-no-transcript": {"claim_id": "gtd.ted-curacao-no-transcript", "unit": "gtd", "source_id": "gtd:S-TED-CURACAO", "claim_type": "unresolved", "statement_zh": "Allen 的 TEDxCuracao（2018）在 ted.com 上只有简介，没有逐字稿（页面数据 hasTranslations 为 false），所以该演讲没有可引用的原话和时间码。", "quote_en": "external brain", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "gtd.ted-claremont-blocked": {"claim_id": "gtd.ted-claremont-blocked", "unit": "gtd", "source_id": "gtd:S-TED-CLAREMONT", "claim_type": "unresolved", "statement_zh": "TEDxClaremontColleges（YouTube 上传于 2012-10-30，1,336 秒）的逐字稿没有取到：ed.ted.com 只有课程外壳，YouTube 字幕地址返回空，Amara 要登录，因此无时间码原话。", "quote_en": "The Art of Stress-Free Productivity", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ver-local-2016": {"claim_id": "pr.ver-local-2016", "unit": "pr", "source_id": "pr:ia-cdx", "claim_type": "official-record", "statement_zh": "本地 PDF 的内容摘要（SHA-1，base32）为 OLGSXWUNTIXTPBX4EDSGSJ2PGSOCGY72，与 bwater.com 上该 PDF 在 2016-03-10 的存档相同，也与 principles.com 在 2016-10-21 的存档相同；bwater.com 在 2016-03-04 的存档仍是另一份摘要 P4PUWXLD5OEFFK2UTEUFCEHD7LLN7ZDW。", "quote_en": "[\"20160310051720\",\"200\",\"application/pdf\",\"OLGSXWUNTIXTPBX4EDSGSJ2PGSOCGY72\",\"1300991\"]", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ver-2015-public": {"claim_id": "pr.ver-2015-public", "unit": "pr", "source_id": "pr:ia-cdx", "claim_type": "official-record", "statement_zh": "2012-01-10 至 2016-03-04 之间，bwater.com 上同一路径的 PDF 摘要始终是 P4PUWXLD5OEFFK2UTEUFCEHD7LLN7ZDW，其中含 2015-08-10、2015-08-12、2015-08-13 的存档；Qureshi 自述 2015 年夏入职，当时公开可取的是这份，不是本地文件。", "quote_en": "[\"20150810102558\",\"200\",\"application/pdf\",\"P4PUWXLD5OEFFK2UTEUFCEHD7LLN7ZDW\",\"1098649\"]", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ver-copyright-2011": {"claim_id": "pr.ver-copyright-2011", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "本地 PDF 首页标注 Copyright © 2011 Ray Dalio，其后每页页脚同标 © 2011 Ray Dalio；pdfinfo 报告文件创建于 2016-03-04，工具为 Adobe InDesign CC 2015。", "quote_en": "Copyright © 2011 Ray Dalio", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "pr.ver-277": {"claim_id": "pr.ver-277", "unit": "pr", "source_id": "pr:newyorker-hitt-2023", "claim_type": "direct-source", "statement_zh": "《纽约客》2023-11-16 的文章称，早期版本的 Principles 有 277 条原则；本地 2011 版的编号到 210 条。", "quote_en": "In an early version of the Principles, there were two hundred and seventy-seven of them.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.qureshi-early-pdf": {"claim_id": "pr.qureshi-early-pdf", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道，Palantir 新人入职时会收到 Impro、The Looming Tower、Interviewing Users、Getting Things Done 四本书；他本人另外拿到一份后来成为 Dalio《Principles》的早期 PDF，并说这“定了调子”。", "quote_en": "I also got an early PDF version of what became Ray Dalio’s Principles. This set the tone.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.qureshi-joined-2015": {"claim_id": "pr.qureshi-joined-2015", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 自述 2015 年夏入职 Palantir，先在新开的伦敦办公室，共工作八年；文章发表于 2024-10-15。", "quote_en": "I joined in summer 2015, initially in the newly-opened London office", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.qureshi-silent": {"claim_id": "pr.qureshi-silent", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "unresolved", "statement_zh": "Qureshi 的文章对 Principles 只有上述一处（两句）：没有说明他拿到的是哪个版本、读了哪几部分、同事是否也拿到、公司内部是否讨论或培训过。", "quote_en": "This set the tone.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.qureshi-terms": {"claim_id": "pr.qureshi-terms", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 把 “dots” 与 “metabolizing pain” 列为 Palantir 的内部用语，并写道其中许多词出自早期员工、尤其是 Shyam Sankar；他没有把这些词归于 Dalio。", "quote_en": "many of these terms came from early employees, especially Shyam Sankar, who’s now the President of the company.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.qureshi-criticism": {"claim_id": "pr.qureshi-criticism", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 称在 Palantir 批评被高度容忍和欢迎，并转述一封邮件：一位入门级软件工程师与一位总监公开而激烈地争论，全公司（约一千人）在抄送。", "quote_en": "it seemed that criticism was highly tolerated and welcomed", "quote_zh": "批评似乎很受容忍，也很受欢迎", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "pr.qureshi-no-titles": {"claim_id": "pr.qureshi-no-titles", "unit": "pr", "source_id": "pr:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道，他在 Palantir 时，除五六位总监和 CEO 外人人是同一头衔，没有人能叫别人做什么，影响力来自成就；他把无头衔的做法追到 Thiel。", "quote_en": "nobody could tell anyone else what to do.", "quote_zh": "谁也不能叫别人做什么。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "pr.agrawal-transparency": {"claim_id": "pr.agrawal-transparency", "unit": "pr", "source_id": "pr:agrawal-founder-foundry", "claim_type": "eyewitness", "statement_zh": "前 Palantir 前线部署工程师 Apoorv Agrawal（2013 至 2017 年任职）写道：公司几乎所有邮件全员可见，重要会议后写会议报告并全公司可见，出了问题把复盘（如 Five Whys）写进内部 wiki；他把这称为 “radical transparency”，全文没有出现 Dalio、Bridgewater 或 Principles。", "quote_en": "Meeting reports were written and shared with the entire company after every important meeting.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.fwd-book-2017": {"claim_id": "pr.fwd-book-2017", "unit": "pr", "source_id": "pr:forwarddeployedbook-list", "claim_type": "direct-source", "statement_zh": "forwarddeployedbook.com 的页面称 Palantir 给每位新人同样五本书，把《Principles: Life and Work》（Simon & Schuster，2017）列为其中之一，并写了一段为何入选的理由；页面没有给出来源。", "quote_en": "Ray Dalio · Simon & Schuster, 2017", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "pr.derivative-flatten": {"claim_id": "pr.derivative-flatten", "unit": "pr", "source_id": "pr:linkedin-das-2024", "claim_type": "inference", "statement_zh": "转述 Qureshi 的社交帖会把“早期 PDF”写成书名，例如 Deedy Das 2024-10-17 的 LinkedIn 帖直接列出 “Principles - Ray Dalio”，版本信息丢失。", "quote_en": "Principles - Ray Dalio", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.baffler-list": {"claim_id": "pr.baffler-list", "unit": "pr", "source_id": "pr:baffler-2016", "claim_type": "direct-source", "statement_zh": "The Baffler 2016-09 的文章写 Palantir 给新员工一份书单，点名 The Looming Tower 与 Impro，没有提到 Dalio 或 Principles。", "quote_en": "gives its new employees a reading list.", "quote_zh": null, "screen_locator": null, "review_state": "unverified"}, "pr.no-firsthand-else": {"claim_id": "pr.no-firsthand-else", "unit": "pr", "source_id": "main:series-search-2026-10", "claim_type": "unresolved", "statement_zh": "本系列检索到的公开网页里，除 Qureshi 外，没有 Palantir 前员工写到 Palantir 怎样使用 Dalio 的 Principles（分发之外的阅读、讨论、培训或对应做法）。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked-with-limits"}, "pr.use-parts": {"claim_id": "pr.use-parts", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p1 作者建议：想用最少功夫抓住全貌，读 Part 1、Part 2，以及 Part 3 开头到 Summary and Table of Principles 为止，约 55 页；Part 2 有助于理解 Part 3，但不是必须。", "quote_en": "I suggest that you read Parts 1 and 2, and the beginning of Part 3 (through the Summary and Table of Principles) which will give you nearly the whole picture.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.use-reference": {"claim_id": "pr.use-reference", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p43 作者说明 Part 3 的 200 多条原则“更像参考书”，不是从头读到尾的书。", "quote_en": "There are over 200 principles here that are well-explained and are meant to be used more as a reference book than a book that is read from cover to cover.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.use-summary": {"claim_id": "pr.use-summary", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p43 说明 Summary and Table of Principles 既是摘要也是目录：想看大意读摘要，想深入再去读其后逐条展开的原则。", "quote_en": "If you want to understand the principles in brief, just read what’s said in the summary below and if you want to delve into them, go to the individual principles after the outline.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.use-not-blind": {"claim_id": "pr.use-not-blind", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p5 作者说这些原则是供读者在遭遇现实时反思的，不是供盲从的，并要求读者对每条原则自问 “Is it true?”。", "quote_en": "So, I put these out there for you to reflect on when you are encountering your realities, and not for you to blindly follow.", "quote_zh": "所以，我把这些拿出来，是供你在遭遇自己的现实时反思，而不是让你盲目照做。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 5", "review_state": "checked"}, "pr.use-200": {"claim_id": "pr.use-200", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p4 作者说他把人们遇到的问题类型与被违反的原则逐一记下，发现约 200 条原则几乎覆盖所有问题；脚注 1 说文档仍在增补。", "quote_en": "I discovered that about 200 principles pretty much cover all the problems.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.truth-15": {"claim_id": "pr.truth-15", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p15 Dalio 把最根本的原则写作：对现实的准确理解是产生好结果的根本基础（“Truth”）。", "quote_en": "Truth —more precisely, an accurate understanding of reality— is the essential foundation for producing good outcomes.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.wish-20": {"claim_id": "pr.wish-20", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p20 第二个决策树：把愿望当作事实的人会形成扭曲的现实图景，因而做不出最好的选择，也无法预见决策的后果。", "quote_en": "People who confuse what they wish were true with what is really true create distorted pictures of reality that make it impossible for them to make the best choices.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.pain-reflect": {"claim_id": "pr.pain-reflect", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p20 个人层面的学习机制：多数学习来自犯错、反思错因、学到下次怎么做不同；疼痛是该去找解法的信号，公式 Pain + Reflection = Progress 在 p20、p33、p56（#18）各出现一次。", "quote_en": "most learning comes from making mistakes, reflecting on the causes of the mistakes, and learning what to do differently in the future.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.pain-others": {"claim_id": "pr.pain-others", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p20 脚注 30：反思时他建议去问其他 believable 的人，请他们帮着找痛苦的根因，尤其是观点相反、又像你一样想找真相而不是想证明自己对的人。", "quote_en": "Asking other believable people about the root causes of your pain in order to enhance your reflections is also typically very helpful", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ego-18": {"claim_id": "pr.ego-18", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p17–18 Dalio 认为进步的障碍是自我防御（ego barriers，由杏仁核的情绪反应触发），而别人帮你找出弱点之所以必要，是因为自己很难看见自己的弱点。", "quote_en": "having others help one find one’s weaknesses is essential because it’s very difficult to identify one’s own.", "quote_zh": "让别人帮自己找出弱点是必不可少的，因为自己的弱点很难由自己认出来。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, pp. 17–18", "review_state": "checked"}, "pr.fail-33": {"claim_id": "pr.fail-33", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p33 Dalio 写道：被指出错误让人难受，所以多数人不愿指出别人的错误；结果，由人的错误引起的问题常常缺少客观诊断，个人的进化因此受阻。", "quote_en": "most people are reluctant to point out mistakes in others. As a result, an objective diagnosis of problems arising from people’s mistakes is often missing and personal evolution is stunted.", "quote_zh": "多数人不愿指出别人的错误。结果，对人的错误引起的问题，常常缺少客观的诊断，个人的进化也受到阻碍。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 33", "review_state": "checked"}, "pr.pain-bounded": {"claim_id": "pr.pain-bounded", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p14 脚注 15 为“痛苦”设限：他不是说痛苦越多越好，过多的痛苦会压垮人，没有痛苦又阻碍成长，应接受与目标相称的量。", "quote_en": "too much pain can break someone and that the absence of pain typically prevents growth", "quote_zh": "过多的痛苦会把人压垮，而没有痛苦通常会妨碍成长", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 14, note 15", "review_state": "checked"}, "pr.machine-loop": {"claim_id": "pr.machine-loop", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p24 起 Dalio 用 Goals → Machine → Outcomes 的反馈环：Machine 由 design 与 people 组成；结果与目标不一致时，要改设计（或文化）或改人。同一张图在 p40–41、p63、p72、p96 重复出现。", "quote_en": "If your outcomes are inconsistent with your goals (e.g., if you are having problems), you need to modify your “machine,” which means that you either have to modify your design/culture or modify your people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.feedback-41": {"claim_id": "pr.feedback-41", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p41 Dalio 认为，伟大组织与糟糕组织最重要的差别，在于反馈回路管理得好不好。", "quote_en": "I also believe that the most important difference between great organizations and bad ones is in how well they manage their feedback loops.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.sample-72": {"claim_id": "pr.sample-72", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p72 #66：要持续比较结果与目标，以积累大样本，因为单个问题可能只是一次性的瑕疵，也可能是反复出现的根因的症状，样本大了才分得清。", "quote_en": "any one problem can either be a one-off imperfection or symptomatic of root causes that will show up as problems repeatedly", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.culture-people-40": {"claim_id": "pr.culture-people-40", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p40 他认为要有一家伟大的公司，必须把文化和人这两件事做好。", "quote_en": "to have a great company you have to make two things great—the culture and the people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.five-26": {"claim_id": "pr.five-26", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p26 五步（目标、识别并不容忍问题、诊断、设计、执行）要当作彼此独立的步骤，不要混在一起：设目标时只设目标，诊断时只诊断。", "quote_en": "must approach these as distinct steps rather than blur them together.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.five-37": {"claim_id": "pr.five-37", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p37 他说如果没有达成目标，可把五步过程当诊断工具：找出失败在哪一步、该步需要哪些品质、自己缺了哪些；p37 的表列出每步所需品质。", "quote_en": "if you are not achieving your goals you can use the 5-Step Process as a diagnostic tool.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.five-36": {"claim_id": "pr.five-36", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p36 他说过程运转正常时，目标的变化远慢于设计，设计的变化慢于任务；常见的失败是次序颠倒——死守任务、对目标不够坚持。", "quote_en": "If this process is working, goals will change much more slowly than designs, which will change more slowly than tasks.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-31": {"claim_id": "pr.diag-31", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p31 他要求不要把问题与成因混为一谈：“睡不够”不是问题而是某个问题的成因；应把问题写成次优的结果，如“我因为累了工作表现差”。", "quote_en": "“I can’t get enough sleep” is not a problem, it is a cause of some problem.", "quote_zh": "“我睡不够”不是问题，它是某个问题的原因。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 31", "review_state": "checked"}, "pr.diag-root": {"claim_id": "pr.diag-root", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p32 近因（proximate cause）通常用动词描述，是导致问题的行动或不作为（“我没查时刻表”）；根因通常用形容词描述，是行为者是什么样的人（“我健忘”）。p93 #162 步骤 2 重述此区分。", "quote_en": "Root causes are typically described with adjectives, usually characteristics about what the person is like that lead them to an action or an inaction.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-jump": {"claim_id": "pr.diag-jump", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p32 他说常见的错误是在认出一个难题后一瞬间就跳到解法，没有花几个小时做诊断和设计，结果是坏决策。", "quote_en": "It is a very common mistake for people to move directly from identifying a tough problem to a proposed solution in a nanosecond without spending the hours required to properly diagnose and design a solution.", "quote_zh": "人们很常犯的一个错误，是认出一个难题之后，一眨眼就直接跳到一个解决方案上，而不花上必要的几个小时，好好诊断问题、设计解决方案。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 32", "review_state": "checked"}, "pr.diag-148": {"claim_id": "pr.diag-148", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p89 #148：不要把问题当一次性事件；问题是你的机器（设计加人）产出的结果，诊断要同时看设计和人。", "quote_en": "Don’t deal with your problems as one-offs. They are outcomes produced by your machine, which consists of design and people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-people": {"claim_id": "pr.diag-people", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p90 #151：根因不是动作而是理由；因为多数事是某个人决定做或不做，多数根因可追到具体的人，尤其是“责任方”，并要像诊断设备故障一样准确地诊断人的问题。", "quote_en": "most root causes can be traced to specific people, especially “the responsible party.”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-questions": {"claim_id": "pr.diag-questions", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p89–90 #150：诊断按六个问题依次问：体验到问题的人、区域经理、责任方（脑中的“心智图”）、责任归属人（设计坏了还是人坏了）、当事人为何这么做（近因与根因）、是否符合既往模式；熟练后只需 10 到 20 分钟。", "quote_en": "If you get adept at the process, it should take 10 to 20 minutes.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-drilldown": {"claim_id": "pr.diag-drilldown", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p92 #162：对出问题的部门做 drilldown——先列问题、再列成因并诊断、再做计划；作者给的耗时是全过程约 5 到 9 小时、分三四次会议，其后执行、监控、修改计划约 6 到 12 个月。", "quote_en": "So the whole process, from asking the first question to coming up with the detailed plan, typically takes about five to nine hours spread over three or four meetings.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-146a": {"claim_id": "pr.diag-146a", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p89 #146a：问题按好坏分四档——未识别（最差）、已识别但无计划、已识别且有好计划、已解决（最好）；他说对士气最糟的是第二档：已识别但没有计划的解决方案。", "quote_en": "the worst situation for morale is the second case: identified but without a planned solution.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-dot": {"claim_id": "pr.diag-dot", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p91 #155：不要对单个“点”（dot，一次具体结果）读过头；要快速收集许多点并与他人互证，综合出一幅更丰富的图景；p104 #206 说通常要诊断同类的约五个点才能看出根因。", "quote_en": "Don’t make too much out of one “dot”—synthesize a richer picture by squeezing lots of “dots” quickly and triangulating with others.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-109a": {"claim_id": "pr.diag-109a", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p81 #109a：“我认为你做了个坏决定”与“我认为你是个坏的决策者”不同，后者只有看到模式才能判断。", "quote_en": "There is also a difference between “I believe you made a bad decision” and “I believe you are a bad decision-maker,” which can be ascertained only by seeing the pattern.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-159": {"claim_id": "pr.diag-159", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p91 #159：评价过去的决策，要问“当时一个合格的人本应知道什么、做什么”，而不是拿现在才知道的信息去评判（避免“事后诸葛亮”）。", "quote_en": "What should a quality person have known and done in that situation?", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-94": {"claim_id": "pr.diag-94", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p94 他说多数公司和个人在这里失败：人们常把“错误”的认定当成对自己有缺陷（笨、懒）的指控而防御；若把它当作对流程可能有何缺陷的调查，就更容易推进。", "quote_en": "people often take the identification of a “mistake” as the equivalent of an accusation that they are flawed (dumb, lazy, etc.), so they become defensive.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-two-levels": {"claim_id": "pr.diag-two-levels", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p73 #69：问题出现时分两层讨论：“机器”层（机器为何产出这个结果）和“个案”层（现在怎么办）；只谈任务层就变成微观管理。", "quote_en": "Conduct the discussion at two levels when a problem occurs: 1) the “machine” level discussion of why the machine produced that outcome and 2) the “case at hand” discussion of what to do now about the problem.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.diag-qualities": {"claim_id": "pr.diag-qualities", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p33 诊断问题最重要的品质是逻辑、看见多种可能的能力，以及“触碰神经”（touch the nerve）的意愿，以越过阻挡真相的自我屏障。", "quote_en": "The most important qualities for successfully diagnosing problems are logic, the ability to see multiple possibilities, and the willingness to touch people’s nerves to overcome the ego barriers that stand in the way of truth.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.mistake-8": {"claim_id": "pr.mistake-8", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p54 #8（目录在 p44）：要建设这样的文化——犯错没关系，但不识别、不分析、不从中学习是不可接受的。", "quote_en": "Create a Culture in Which It Is OK to Make Mistakes but Unacceptable Not to Identify, Analyze, and Learn From Them", "quote_zh": "建立这样一种文化：犯错没关系，但不识别、不分析、不从中学习，是不可接受的", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #8", "review_state": "checked"}, "pr.mistake-15": {"claim_id": "pr.mistake-15", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p55 #15：不要把错误去个人化；诊断必须把错误连到具体的人并点名，说“Harry 处理得不好”而不是“我们处理得不好”。", "quote_en": "the diagnosis must connect the mistake to the specific individual by name.", "quote_zh": "诊断必须把错误连到具体的个人，并点出名字。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #15", "review_state": "checked"}, "pr.log-mandatory": {"claim_id": "pr.log-mandatory", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p56 #19a：issues log 是纠错最有价值的工具，作者说使用它是强制的，因为强制比留作选项好得多。", "quote_en": "Using this tool is mandatory because we believe that enforcing this behavior is far better than leaving it optional.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.log-asymmetry": {"claim_id": "pr.log-asymmetry", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p88 #144：出了事却没记进 issues log 的，相关人员“应该有大麻烦”；出了事且已记入（理想情况下已诊断好）的，相关人员多半会受奖励或表扬；但必须有个人问责。", "quote_en": "If, for example, something goes wrong and it’s not in the issues log, the relevant people should be in big trouble.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.mistake-bounded": {"claim_id": "pr.mistake-bounded", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p84 #124：对“可以犯的错”设有上限：作者愿意让人刮蹭车，但不会让他处在有显著风险把车撞毁的位置；要把错误可能的损失与渐进学习的收益相权衡。", "quote_en": "I’m willing to let you scratch or dent the car, but I won’t put you in a position where I think there’s a significant risk you could total it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.opt-209": {"claim_id": "pr.opt-209", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p106 #209：Dalio 写道常有人要求让很棒的人免于探查自己的错误与弱点（因为痛苦），他不让步，理由是允许退出会使两套规则合法化，危及 “radically honest” 的方式。", "quote_en": "I also believe that to allow opt-outs would legitimatize two sets of rules and put our radically honest way of being in jeopardy.", "quote_zh": "我还认为，允许有人退出，就会让两套规则都名正言顺，并危及我们彻底坦诚的处事方式。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #209", "review_state": "checked"}, "pr.rt-3": {"claim_id": "pr.rt-3", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p53 #3：要营造这样的环境——人人有权弄懂什么说得通，同时没有人有权对某事持批评意见却不说出来。", "quote_en": "Create an environment in which everyone has the right to understand what makes sense and no one has the right to hold a critical opinion without speaking up about it.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.rt-6a": {"claim_id": "pr.rt-6a", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p54 #6a：不含保密信息的会议要录音并分享给相关人员；#6 的要求是让人尽可能多地接触周围发生的事，涉及保密信息时在获准前保密。", "quote_en": "Provide tapes of all meetings that don’t contain confidential information to enhance transparency.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.rt-wording": {"claim_id": "pr.rt-wording", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "2011 PDF 全文没有名词短语 “radical transparency”；对应处是动词式原则 #6 “Be radically transparent”（p44、p54）。", "quote_en": "Be radically transparent.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.rt-4": {"claim_id": "pr.rt-4", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p53 #4：Dalio 认为 Bridgewater 表现好的主要原因，是所有人都有权公开且平等地发言，其观点按内容的是非来评判。", "quote_en": "The main reason Bridgewater performs well is that all people here have the power to speak openly and equally and because their views are judged on the merits of what they are saying.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-24": {"claim_id": "pr.dis-24", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p57 #24：要同时坚持己见和开放心态；目的是找出什么是真的，不是赢得争论，发现自己错了比正确更有价值。", "quote_en": "Be assertive and open-minded at the same time. Just try to find out what is true. Don’t try to “win” the argument.", "quote_zh": "要同时坚持己见和保持开放。只管设法弄清什么是真的，不要试图“赢”下争论。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #24", "review_state": "checked"}, "pr.dis-26b": {"claim_id": "pr.dis-26b", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p58 #26b：他认为分歧中有巨大的未开发潜力，尤其当分歧发生在两个以上深思的人之间，而多数人要么回避、要么把它变成无益的争吵。", "quote_en": "There is giant untapped potential in disagreement, especially if the disagreement is between two or more thoughtful people", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-29": {"claim_id": "pr.dis-29", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p58 #29：沟通分三种：辩论多在大致对等者之间，讨论是不同理解水平者的开放探讨，教学是理解水平不同者之间；选哪种要看目的和各方的 believability，并要事先说明是哪一种。", "quote_en": "Debate is generally among approximate equals; discussion is open-minded exploration among people of various levels of understanding; and teaching is between people of different levels of understanding.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-27a": {"claim_id": "pr.dis-27a", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p58 #27a：当人们对“某事值不值得辩论”本身有分歧时就应当辩论，否则等于给某个人（通常是老板）事实上的否决权；同条 #27 前文要求知道何时停止争论、转入对该怎么做达成一致。", "quote_en": "Operating otherwise would essentially give someone (typically the boss) a de facto veto right.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-no-referendum": {"claim_id": "pr.dis-no-referendum", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p61–62 #34：Dalio 不主张共识决策或全员投票；责任与权限分给具体的人，责任方即使在知情者反对时也可照自己判断执行，但要认真权衡这些反对意见。", "quote_en": "It is perfectly OK for a responsible party to carry through a decision he thinks is best even when others who are knowledgeable disagree, although this disagreement should be considered and weighed seriously.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-hierarchy": {"claim_id": "pr.dis-hierarchy", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p62 #34：作者说 Bridgewater 有、而且应该有一套明确的决策层级，最好基于才干（merit）。", "quote_en": "We have, and should have, an explicit decision-making hierarchy, ideally based on merit.", "quote_zh": "我们有、也应该有一套明确的决策层级，最好以才干为基础。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #34", "review_state": "checked"}, "pr.dis-escalate": {"claim_id": "pr.dis-escalate", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p57 #25（并见 p62 #36）：出现分歧时可上诉给经理的上级，或一个双方认可的、有知识的小组，通常包含比决策者更 believable、更资深的人；裁决者必须客观公平，否则这套系统守不住“思想择优”。", "quote_en": "in the event of disagreement, an appeal should be made to either the manager’s boss or an agreed-upon, knowledgeable group of others, generally including people more believable than and senior to the decision-maker.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dis-33d": {"claim_id": "pr.dis-33d", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p60 #33d：他认为 3 到 5 个聪明、重概念且开放的人组成的小组通常给出最好的答案；其次是单个这样的决策者；最差的是没有这样领导者的大群体。", "quote_en": "A small group (3 to 5) of smart, conceptual people seeking the right answers in an open-minded way will generally lead to the best answer.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-30": {"claim_id": "pr.bel-30", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p59 #30：不要把所有意见看得同样有价值；没有成功记录者的看法不等于有成功记录者的看法；#30a 称“优选层级”不但与思想择优一致，而且是它的必要条件。", "quote_en": "The views of people without track records are not equal to the views of people with strong track records.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-31": {"claim_id": "pr.bel-31", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p59 #31：believability 的定义是一个人的看法正确的概率；无法精确知道，但可按其推理质量和过往记录粗略评估；遇到时先问“我为什么该信你”“我为什么该信自己”。", "quote_en": "By believability, I mean the probability that a person’s view will be right. While we can never know this precisely, we can roughly assess it according to the quality of a person’s reasoning and their track record.", "quote_zh": "我说的可信度，是指一个人的看法正确的概率。我们永远无法精确知道它，但可以根据一个人推理的质量和他过往的记录，粗略地评估它。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #31", "review_state": "checked"}, "pr.bel-31b": {"claim_id": "pr.bel-31b", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p60 #31b：反复成功做成过所讨论之事、且被追问时能给出很好解释的人最 believable；只具备其一的人有些 believable；二者皆无的人最不 believable。", "quote_en": "People who have repeatedly and successfully accomplished the thing in question and have great explanations when probed are most believable. Those with one of those two qualities are somewhat believable; people with neither are least believable.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-merit": {"claim_id": "pr.bel-merit", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p60 #31b：believability 之外，意见仍应一律就其内容的是非来评估，以鼓励人保持开放；作者说没经验的人有时有极好的想法，也常常差得多。", "quote_en": "At the same time, people’s ideas should always be assessed on their merit in order to encourage them to always think in an open-minded way.", "quote_zh": "与此同时，人们的想法始终应当按其本身的是非来评估，以鼓励他们始终以开放的心态思考。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #31b", "review_state": "checked"}, "pr.bel-golfer": {"claim_id": "pr.bel-golfer", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p59 #29c 的例子：新手与 Tiger Woods 辩论挥杆时把两人看法同等对待是有害的；但作者同时说，新手也不该只因对方赢过很多比赛就接受，应继续追问到自己确信找到了真相，同时别自以为比冠军对。", "quote_en": "I believe the new golfer shouldn’t stop questioning Tiger until he is confident he has found truth.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-matrix": {"claim_id": "pr.bel-matrix", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p62 脚注 54：Dalio 说他曾考虑过基于 believability 矩阵的投票系统，并说出于实际原因可能做不到；p78 #101b 则只建议为员工维护 “baseball cards” 和/或 “believability matrixes”。", "quote_en": "I once toyed with the possibility of developing a voting system based on a believability matrix.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-194": {"claim_id": "pr.bel-194", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p102 #194：人人都有权提问和提出理论，但只有 believable 的人才有权持有意见。", "quote_en": "While everyone has the right to have questions and theories, only believable people have the right to have opinions.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-195b": {"claim_id": "pr.bel-195b", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p102 #195b：任何重要决定前，至少问三位 believable 的人；不要问他们的结论或照他们说的做，而要弄懂、想象并评估他们的推理，也请他们检验你的推理。", "quote_en": "Never make any important decisions without asking at least three believable people.", "quote_zh": "没有问过至少三位可信的人，绝不做任何重要的决定。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, #195b", "review_state": "checked"}, "pr.bel-191": {"claim_id": "pr.bel-191", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p102 #191：目标是找到最好的答案，自己拥有它的概率很小，即便拥有也无法确信，除非有别的 believable 的人来检验你。", "quote_en": "even if you have it, you can’t be confident that you do have it unless you have other believable people test you.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-197c": {"claim_id": "pr.bel-197c", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p103 #197c：把“正确的概率”从 51% 提到 85% 的价值，可能高于从 45% 提到 51%；多数人在觉得有五成以上把握时就开口，而不去提升把握。", "quote_en": "raising the probability of being right (e.g., from 51% to 85%) can be worth more than just going from probably being wrong (e.g., 45%) to probably being right (e.g., 51%)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.bel-ruin": {"claim_id": "pr.bel-ruin", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p102 #197：按概率和收益做决定，要保证“不可接受之事”（破产风险）的概率为零。", "quote_en": "make sure that the probability of the unacceptable (i.e., the risk of ruin) is nil.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-38": {"claim_id": "pr.people-38", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p63 #38：几乎所有好事都来自伟大的人在伟大的文化中工作；他把人的选拔、培训、测试、评估、分流称为反馈环中“人”的那一半。", "quote_en": "Remember that almost everything good comes from having great people operating in a great culture.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-39a": {"claim_id": "pr.people-39a", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p63 #39：先让人与设计匹配；#39a 称 Bridgewater 的核心价值观是追求卓越、“truth at all costs”、高度的主人翁意识和强品格（愿意做好而困难的事）。", "quote_en": "At Bridgewater, those key values are a drive for excellence, truth at all costs, a high sense of ownership, and strong character", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-40": {"claim_id": "pr.people-40", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p63 #40：不可避免的责任方（RP）是承担所做之事后果的人，所以必须慎选并管理被委托者；不能把责任全部委托出去再期待好结果。", "quote_en": "the inevitable responsible party (RP) is the person who bears the consequences of what is done.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-45": {"claim_id": "pr.people-45", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p64 #45：挑选长期关系的人时，价值观最重要，能力其次，技能最次。", "quote_en": "In picking people for long-term relationships, values are most important, abilities come next, and skills are the least important.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-design-first": {"claim_id": "pr.people-design-first", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p98 #174a：先做出最佳工作流设计，画成组织图、说明每个岗位需要的品质，之后才选人填岗；#174 的总原则是围绕目标而不是任务来建组织。", "quote_en": "only after that is done, choose the right people to fill the jobs", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-not-fit": {"claim_id": "pr.people-not-fit", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p99 #175f：不要为迁就人而建组织；岗位按需要完成的工作设置，而不是按人想做什么或手头有什么人。", "quote_en": "Jobs are created based on the work that needs to be done, not what people want to do or what people are available.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-129": {"claim_id": "pr.people-129", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p84 #129：作者说为迁就员工弱点而改设计通常是坏主意，所以更好的办法是把人分流（调岗或辞退）。", "quote_en": "Since changing the design to accommodate people’s weaknesses is generally a bad idea, it is generally better to sort the people.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-tension": {"claim_id": "pr.people-tension", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "inference", "statement_zh": "同一份文件里，Part 2（p26）说个人认清弱点后可以“围绕弱点做设计”，Part 3 #129（p84）却说为迁就员工弱点而改设计通常是坏主意、应换人；前者对自己，后者对下属，两处不能混着引。", "quote_en": "if you recognize your weaknesses and design around them.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-18m": {"claim_id": "pr.people-18m", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p84 #125：行为改变通常需要约 18 个月的持续强化；p82 #115 说要对一个人的角色适配做较有把握的判断，也大约需要 18 个月。", "quote_en": "Recognize that behavior modification typically takes about 18 months of constant reinforcement.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.people-science-hedge": {"claim_id": "pr.people-science-hedge", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "p65 讲人们思维能力差异的一节开头，作者说关于人如何思考的理论很多，几乎不该当作事实，随后列的是“我相信但并非确定”的内容（左脑/右脑、细节/全局等分类）。", "quote_en": "I have also found that there are all sorts of theories from all sorts of people about how people think and why, so very little should be treated as fact.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ny-dispute": {"claim_id": "pr.ny-dispute", "unit": "pr", "source_id": "pr:newyorker-hitt-2023", "claim_type": "direct-source", "statement_zh": "关于 Bridgewater 内部实际怎样使用 Principles，有记者著作（Copeland 的《The Fund》）的描述；据《纽约客》转述，Dalio 与 Bridgewater 都称该书的描述不准确，包括对 Principles 如何被使用的部分。", "quote_en": "Both Dalio and Bridgewater maintain that the book provides an inaccurate portrayal of the company, including the way that Dalio’s Principles were used.", "quote_zh": "Dalio 和 Bridgewater 都坚持认为，这本书对公司的描绘不准确，包括对 Dalio 的原则如何被使用的描绘。", "screen_locator": "Tarpley Hitt, The New Yorker, 2023-11-16", "review_state": "checked"}, "pr.ted-meta": {"claim_id": "pr.ted-meta", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "official-record", "statement_zh": "Dalio 的 TED 演讲录于 2017-04-24、发布于 2017-09-06，时长 984 秒（16 分 24 秒），晚于 2011 版文本约六年，也晚于 Qureshi 2015 年夏入职。", "quote_en": "\"recordedOn\":\"2017-04-24\"", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-algo": {"claim_id": "pr.ted-algo", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 开场把主题定为 radical transparency 与算法化决策；2011 PDF 全文没有 “algorithm” 一词（0 处）。", "quote_en": "Whether you like it or not, radical transparency and algorithmic decision-making is coming at you fast, and it's going to change your life.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-idea": {"claim_id": "pr.ted-idea", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 里 Dalio 用 “idea meritocracy” 称其目标；2011 PDF 无此词（0 处），用的是 “meritocracy of ideas”（p45、p57、p59、p62）和 “meritocracy of thought”（p53）。", "quote_en": "I wanted to have an idea meritocracy in which the best ideas would win out.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-dot": {"claim_id": "pr.ted-dot", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 展示名为 Dot Collector 的工具：会议中给他人的思维属性打 1 到 10 分，汇总成“点彩画”；2011 PDF 无此工具名（0 处），其中的 dot 只指单次观察或结果（#155 p91、#206 p104）。", "quote_en": "a tool of ours called the \"Dot Collector\" that helps us do this.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-believ": {"claim_id": "pr.ted-believ", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 称决策用把 believability 纳入考虑的算法来做，既不是民主也不是独裁；2011 PDF 对应处只有加权投票的设想（p62 脚注 54）和手工的 believability matrix（#101b，p78）。", "quote_en": "This process allows us to make decisions not based on democracy, not based on autocracy, but based on algorithms that take people's believability into consideration.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-25": {"claim_id": "pr.ted-25", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 里 Dalio 说这种方式对大约 25% 到 30% 的人群行不通；2011 PDF 的 #209 则写他拒绝为“很棒的人”开退出口，理由是两套规则会危及整体做法。", "quote_en": "We found something like 25 or 30 percent of the population it's just not for.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.ted-18": {"claim_id": "pr.ted-18", "unit": "pr", "source_id": "pr:ted-dalio-2017", "claim_type": "direct-source", "statement_zh": "TED 里的“18 个月”指大多数人学会偏好这种透明所需的时间；2011 PDF 里的 18 个月指行为改变需约 18 个月的持续强化（#125 p84），以及对角色适配有把握的判断（#115 p82）——数字相同，指代不同。", "quote_en": "It takes about 18 months typically to find that most people prefer operating this way, with this radical transparency than to be operating in a more opaque environment.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.qur-pack": {"claim_id": "lt.qur-pack", "unit": "lt", "source_id": "lt:S01", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道：新员工入职时会收到 Impro、The Looming Tower（他注明是讲 9/11 的书）、Interviewing Users 和 Getting Things Done，他本人还拿到后来成为 Ray Dalio《Principles》的早期 PDF；他说不确定公司现在是否还这样做。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.qur-reason": {"claim_id": "lt.qur-reason", "unit": "lt", "source_id": "lt:S01", "claim_type": "eyewitness", "statement_zh": "Qureshi 给 The Looming Tower 的理由只有一句：这本书的用意显而易见，因为公司部分地是为回应 9/11 以及 Peter（Thiel）认为随之而来的对公民自由的侵犯而创立，书提供的是背景。这一处没有提到机构之间的信息共享或信息孤岛。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.qur-gatekeepers": {"claim_id": "lt.qur-gatekeepers", "unit": "lt", "source_id": "lt:S01", "claim_type": "eyewitness", "statement_zh": "Qureshi 把客户侧数据整合难的主要原因归为组织政治：某个团队掌握关键数据源，并靠做这个数据源的守门人来证明自己存在。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.qur-controls": {"claim_id": "lt.qur-controls", "unit": "lt", "source_id": "lt:S01", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道：Palantir 较早发现，数据访问之争一部分出于真实的安全顾虑，于是在数据整合层的各个层级内置基于角色的访问控制、行级策略、安全标记和审计日志。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.s1-founding": {"claim_id": "lt.s1-founding", "unit": "lt", "source_id": "lt:S10", "claim_type": "official-record", "statement_zh": "Palantir 的 S-1（2020 年 8 月 25 日提交）自述公司成立于 9/11 袭击之后；同一文件称公司 2003 年成立，起初为美国情报界的反恐调查与行动开发软件。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.s1-civil": {"claim_id": "lt.s1-civil", "unit": "lt", "source_id": "lt:S10", "claim_type": "official-record", "statement_zh": "同一份 S-1 称公司把隐私与公民自由保护当作软件的必备要求，“从一开始”就内置数据保护与治理能力，包括端到端数据可追溯、审计日志、细粒度访问控制、数据质量检查和用途限定。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.pub-excerpt": {"claim_id": "lt.pub-excerpt", "unit": "lt", "source_id": "lt:S02", "claim_type": "direct-source", "statement_zh": "The Looming Tower 目前能合法读到的正文只有开篇《The Martyr》节选（Sayyid Qutb 1948 年 11 月乘船赴美），约 2,400 余词；本次重新核对，节选里没有出现 CIA、FBI、情报、机构或 9/11 这些词。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ct-swap": {"claim_id": "lt.ct-swap", "unit": "lt", "source_id": "lt:S04", "claim_type": "direct-source", "statement_zh": "Wright 在 2002 年 1 月 14 日刊的《The Counter-Terrorist》里写道：1995 年一道总统指令给了 FBI 在调查和预防恐怖主义上的牵头权；O'Neill 安排他的办公室与 CIA 反恐中心互派副手，两个机构都曾抵制。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ct-need-both": {"claim_id": "lt.ct-need-both", "unit": "lt", "source_id": "lt:S04", "claim_type": "direct-source", "statement_zh": "同文引 FBI 探员 John Lipka 转述 O'Neill 的话：把 CIA 反恐中心与 FBI 反恐科的资源和人才合在一起，任何问题都能解决，但两边都要有；1996 年 1 月 O'Neill 还协助设立了代号 Alex 的 CIA 专门站，盯本·拉登的基础设施、资金和基地。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ct-no-mihdhar": {"claim_id": "lt.ct-no-mihdhar", "unit": "lt", "source_id": "lt:S04", "claim_type": "direct-source", "statement_zh": "这篇 2002 年的文章没有出现 Mihdhar 或 Hazmi 的名字，也没有 CIA 向 FBI 隐瞒情报的指控；它只写到 2000 年 1 月马来西亚聚会的参与者中至少两人后来被认定为 9/11 劫机者，并引一名克林顿政府官员说当时没有一张脸出现在美方自己的档案里。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.ag-nopass": {"claim_id": "lt.ag-nopass", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 在 The Agent 里写道：约 1999 年底，CIA 从也门 Hada 电话的一次通话得知马来西亚将有基地组织聚会，知道参会者之一叫 Khaled al-Mihdhar、另一人名 Nawaf，两人都是沙特人；CIA 没有把这条情报转给 FBI。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-passport": {"claim_id": "lt.ag-passport", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：CIA 闯入迪拜一间酒店房间，复印 Mihdhar 的护照并传真给 Alec Station，护照里有美国签证；CIA 没有通知 FBI 或国务院，Mihdhar 因而没有进入恐怖分子观察名单，也没被挡在美国之外。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-mission": {"claim_id": "lt.ag-mission", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 给出的解释之一是使命不同：FBI 搜集情报是为了把人定罪，CIA 把情报本身当目标；两个机构长期争地盘，各自的授权把它们放在对立面。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-animus": {"claim_id": "lt.ag-animus", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：CIA 在法律上有义务与 FBI 分享此类情报，却护着敏感情报；CIA 尤其提防要求掌控一切相关案件的 O'Neill，Alec Station 创办人 Michael Scheuer 称 O'Neill 言行两面；FBI 方面的人则认为 CIA 出于个人恩怨而隐瞒。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-overload": {"claim_id": "lt.ag-overload", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 同时给出更平淡的解释：CIA 未告知 FBI 的缘由或许最好用“当时被大量威胁信息淹没、没有看到这条情报的关键性”来解释；FBI 的 Kenneth Maxwell 说，两个基地组织的人住在加州，FBI 会对他们全面物理和电子监视。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-wilshire": {"claim_id": "lt.ag-wilshire", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：2001 年春，CIA 派驻 FBI 总部的联络官 Tom Wilshire 已知 Hazmi 在美国、Mihdhar 可能同行，申请向 FBI 披露，其 CIA 上级从未答复；CIA 的官方声明质疑文章准确性，但没有回应具体指控。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-june11": {"claim_id": "lt.ag-june11", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：2001 年 6 月 11 日纽约会议上，CIA 的 Clark Shannon 不肯说明是否还有其他照片，也没有被授权透露 Mihdhar 的美国签证、他与 Hazmi 的关联以及两人与 Khallad、基地组织的关系；FBI 的 Steve Bongardt 要出生日期或护照号，同样被拒。Wright 称此据 9/11 委员会报告。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-trend": {"claim_id": "lt.ag-trend", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 把 6 月 11 日会议称为美国政府一个奇怪趋势的顶点：向最需要信息的人隐藏信息；他并指出在这一点上 FBI 与 CIA 同样有责，FBI 把大陪审团保密规定当作近乎绝对的禁令。", "quote_en": "“hiding information from the people who most needed it” (Wright, The New Yorker)", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-wall": {"claim_id": "lt.ag-wall", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：1995 年司法部的“墙”政策被 FBI 总部管理者误解，变成束缚自家调查员的紧身衣；情报探员被警告与刑事探员共享信息可能终结职业，FBI 认定墙甚至隔开同一小队里的人。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-email": {"claim_id": "lt.ag-email", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：2001 年 8 月 FBI 分析员 Dina Corsi 的邮件说，因为“墙”，刑事侦查人员不能参与寻找 Mihdhar；能找人的情报探员只有一名，而且是新手；Bongardt 在邮件里预言总有人会死，并说不论有没有墙，公众都不会理解为什么没有更有效。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-tenet": {"claim_id": "lt.ag-tenet", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：9/11 之后 CIA 称已及时把 Mihdhar 的身份告知 FBI，局长 Tenet 与反恐中心主任 Cofer Black 都向国会这样作证；9/11 委员会后来认定两人的说法为假，CIA 拿不出证明信息已传给 FBI 的证据。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ag-antennas": {"claim_id": "lt.ag-antennas", "unit": "lt", "source_id": "lt:S03", "claim_type": "direct-source", "statement_zh": "Wright 写道：FBI 的 I-49 小队为应对 CIA 拒绝分享，另起炉灶——在太平洋的 Palau 和印度洋的 Diego Garcia 设天线截获本·拉登的卫星电话信号，并在坎大哈自建卫星电话亭监听；数百万美元和数千小时被花在重复其他美国官员拒绝分享的信息上。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.in-berkeley-three": {"claim_id": "lt.in-berkeley-three", "unit": "lt", "source_id": "lt:S05", "claim_type": "direct-source", "statement_zh": "Wright 在 2006 年 UC Berkeley 的 Conversations with History 访谈里说：Soufan 与 O'Neill 就吉隆坡会面三次向 CIA 询问，三次都被拒绝回应；CIA 知道这次会面，请马来西亚方面监视过，手里有包括 Cole 案策划者和两名后来的劫机者的照片。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-berkeley-march": {"claim_id": "lt.in-berkeley-march", "unit": "lt", "source_id": "lt:S05", "claim_type": "direct-source", "statement_zh": "Wright 在同一访谈里说：2000 年 3 月 CIA 就知道两名基地组织成员在美国，却拒绝告诉 FBI；他称 FBI 在 bin Laden 起诉书之下本有全部所需权限，在 9/11 前二十个月里去跟踪他们。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-siege": {"claim_id": "lt.in-siege", "unit": "lt", "source_id": "lt:S05", "claim_type": "direct-source", "statement_zh": "Wright 说，1990 年代中期他为电影 The Siege 找题材时，意识到 CIA 在冷战后真正的对手是 FBI，双方争的是谁来掌管美国境内的反恐。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-tiers": {"claim_id": "lt.in-tiers", "unit": "lt", "source_id": "lt:S06", "claim_type": "direct-source", "statement_zh": "Wright 2018 年在 9/11 纪念馆的对谈中给出两层解释：一是机构使命不同——CIA 收集情报并预测，FBI 抓人并交付审判；二是个人对立，如 O'Neill 与 Scheuer 各自代表所在机构的立场却把它变成私人恩怨，使裂痕加深。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-wall-myth": {"claim_id": "lt.in-wall-myth", "unit": "lt", "source_id": "lt:S06", "claim_type": "direct-source", "statement_zh": "Wright 在同一场对谈中说，那堵“墙”更像是机构内部的一种迷思：认为情报侧的信息不能传给刑事侧、反之亦然；结果是 FBI 的刑事探员接触不到本局情报部门收集的内容，用他的话说，FBI 自己都不知道自己知道什么。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-cooperate": {"claim_id": "lt.in-cooperate", "unit": "lt", "source_id": "lt:S06", "claim_type": "direct-source", "statement_zh": "Wright 2018 年在同一场对谈中说：9/11 之后这么多年没有人为本可阻止而未阻止的失败问责；如果 FBI 与 CIA 合作，尤其是与 Soufan 合作，本有机会阻止这次袭击。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.in-pbs": {"claim_id": "lt.in-pbs", "unit": "lt", "source_id": "lt:S07", "claim_type": "direct-source", "statement_zh": "Wright 2018 年 2 月在 PBS NewsHour 谈 Hulu 剧集时说，本季主题是“divided, we fail”，并说美国当年是分裂的，没能阻止 9/11。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ind-lead": {"claim_id": "lt.ind-lead", "unit": "lt", "source_id": "lt:S12", "claim_type": "unresolved", "statement_zh": "IndieWire 报道 Wright 在 2019 年一次电视学院座谈上说：若 CIA 及时与 FBI 合作，他认为 9/11 不会发生。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.eye-soufan-queries": {"claim_id": "lt.eye-soufan-queries", "unit": "lt", "source_id": "lt:S06", "claim_type": "eyewitness", "statement_zh": "Ali Soufan 在 2018 年对谈中说：他就东南亚会面三次书面询问——2000 年 11 月、2001 年 4 月、6 月——每次被告知不知情，他都信了；9 月 12 日他收到一份文件夹，里面是他自 2000 年 11 月起一直索要的全部信息。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.eye-soufan-individuals": {"claim_id": "lt.eye-soufan-individuals", "unit": "lt", "source_id": "lt:S06", "claim_type": "eyewitness", "statement_zh": "Soufan 在同一场对谈的问答中说：这件事“不是机构性的”，而是个别人决定不分享；他不知道原因；9/11 之后 FBI 与 CIA 都建立了制度，防止个人再这样做。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-oipr": {"claim_id": "lt.rep-oipr", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "9/11 委员会写道：司法部情报政策与审查办公室（OIPR）成了 FISA 信息流向刑事检察官的把关人。", "quote_en": "The Office of Intelligence Policy and Review became the gatekeeper for the flow of FISA information to criminal prosecutors.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-wall-misapplied": {"claim_id": "lt.rep-wall-misapplied", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：1995 年 7 月司法部长 Reno 发布的、规范 FBI 与检察官之间情报共享的正式程序几乎立刻被误解和误用，实际共享远少于程序允许；后来这套做法被叫作“墙”，委员会认为这个词有误导性，真实情形是多重障碍的叠加。", "quote_en": "The term “the wall” is misleading, however, because several factors led to a series of barriers to information sharing that developed.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-samesquad": {"claim_id": "lt.rep-samesquad", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：来自 OIPR、FBI 领导层和 FISA 法院的压力，在探员之间筑起了屏障，连同一小队里的探员也被隔开。", "quote_en": "pressure from the Office of Intelligence Policy Review, FBI leadership, and the FISA Court built barriers between agents—even agents serving on the same squads.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-bryant": {"claim_id": "lt.rep-bryant", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：FBI 副局长 Bryant 通过告诉探员信息共享过多可能是“职业终结者”，强化了 OIPR 的谨慎。", "quote_en": "FBI Deputy Director Bryant reinforced the Office’s caution by informing agents that too much information sharing could be a career stopper.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-reviews": {"claim_id": "lt.rep-reviews", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：1999、2000、2001 年三次独立审查都得出结论——信息共享没有发生，1995 年程序的本意被例行忽视。", "quote_en": "Separate reviews in 1999, 2000, and 2001 concluded independently that information sharing was not occurring", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-visa-not-shared": {"claim_id": "lt.rep-visa-not-shared", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：2000 年 1 月 CIA 得知 Mihdhar 持美国签证、3 月得知 Hazmi 曾于 1 月 15 日飞往洛杉矶，这些信息都没有送到 FBI；CIA 也没有把二人登记到国务院的 TIPOFF 观察名单，无论 1 月还是 3 月。", "quote_en": "None of this information—about Mihdhar’s U.S. visa or Hazmi’s travel to the United States—went to the FBI", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-fbi-briefed": {"claim_id": "lt.rep-fbi-briefed", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会同时写道：CIA 反恐中心曾就吉隆坡聚会向 CIA 领导层简报，信息也传给了 Berger 与 NSC 工作人员以及 FBI 局长 Freeh 等人，FBI 当时记下的是 CIA 牵头、有国内线索会通知 FBI。", "quote_en": "though the FBI noted that the CIA had the lead and would let the FBI know if a domestic angle arose", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-note44": {"claim_id": "lt.rep-note44", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会第 6 章注 44 写道：带有美国签证的护照复印件被转回 CIA 总部，直到 2001 年 8 月才与 FBI 总部共享；一名派驻 CIA 本·拉登小组的 FBI 探员想通知 FBI 总部，被 CIA 桌面官员指示不要发这份电报；数小时后同一官员起草了只在 CIA 内部流转、称已与 FBI 共享的电报，她承认自己没有亲自共享，委员会找不到任何自称共享过的人。", "quote_en": "A CIA desk officer instructed him not to send the cable with this information.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-march-notice": {"claim_id": "lt.rep-march-notice", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：2000 年 3 月曼谷报告 Hazmi 于 1 月 15 日飞往洛杉矶，因为 CIA 没有意识到这个名字的重要性、也没有留意那份电报，找不到证据表明该信息被送到 FBI。", "quote_en": "Since the CIA did not appreciate the significance of that name or notice the cable, we have found no evidence that this information was sent to the FBI.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-tenet": {"claim_id": "lt.rep-tenet", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：Tenet 与 Cofer Black 在国会联合调查中作证称 FBI 一开始就能接触到对 Khallad（2001 年 1 月）的识别；委员会依据一份包括起草该证词的 CIA 人员当时没看到的文件在内的大量记录，认定事实并非如此，FBI 的主要 Cole 案调查人员直到 9/11 之后才知道 Khallad 曾与 Mihdhar 同在吉隆坡。", "quote_en": "But drawing on an extensive record, including documents that were not available to the CIA personnel who drafted that testimony, we conclude this was not the case.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-goodwill": {"claim_id": "lt.rep-goodwill", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会称，2001 年 1 月 Khallad 识别未传给 FBI 一事说明：即使双方善意，日常的信息共享缺口也会出现——原因包括联合线人几乎不会说英语、CIA 官员通常不翻译问答、FBI 探员能拿到 CIA 向外传发的报告，却看不到含更多细节的 CIA 内部作业报告。", "quote_en": "This incident is an example of how day-to-day gaps in information sharing can emerge even when there is mutual goodwill.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-zone": {"claim_id": "lt.rep-zone", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会借一名 CIA 官员的话对比两种办案方式：CIA 打“区域防守”，盯“在哪里”而不是“是谁”；FBI 打“人盯人”；若信息共享，两者结合本可有效。", "quote_en": "The CIA’s zone defense concentrated on “where,” not “who.”", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-dave": {"claim_id": "lt.rep-dave", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写 2001 年 6 月 11 日纽约会议：CIA 分析员（化名 Dave）知道 Mihdhar 持美国签证、签证申请表写明要去纽约、Hazmi 去了洛杉矶、有线人把 Mihdhar 与 Khallad 放在一起；会上没人问他，他也没主动说，他对调查人员说，作为 CIA 分析员他无权回答 FBI 关于 CIA 信息的问题；纽约探员空手而归。", "quote_en": "He told investigators that as a CIA analyst, he was not authorized to answer FBI questions regarding CIA information.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-jane": {"claim_id": "lt.rep-jane", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写同次会议：FBI 分析员（化名 Jane）手里的 NSA 报告带有“未经 OIPR 许可不得向刑事调查人员提供”的限制，她据此认为不能向纽约探员透露内容；这些信号情报把 Mihdhar 与一处疑似恐怖设施联系起来，探员本可由此建立联系；委员会称讽刺之处在于，找到线人的探员被挡在自己工作的成果之外。", "quote_en": "The sad irony is that the agents who found the source were being kept from obtaining the fruits of their own work.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-email": {"claim_id": "lt.rep-email", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会 p.271 引了一名 Cole 案探员 2001 年 8 月的愤怒邮件：他预言总有人会死，不论有没有墙，公众都不会理解为什么没有投入全部资源。", "quote_en": "someday someone will die—and wall or not—the public will not understand why we were not more effective and throwing every resource we had at certain “problems.”", "quote_zh": "总有一天会有人死——不管有没有墙，公众都不会明白，我们为什么没能更有效，为什么没有把手上的所有资源都投到某些“问题”上。", "screen_locator": "The 9/11 Commission Report, 2004, p. 271", "review_state": "checked"}, "lt.rep-confused": {"claim_id": "lt.rep-confused", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：所有相关人员对情报渠道所得信息的共享和使用规则都弄错了；Mihdhar 因与 Cole 案有关，本可在既有的 Cole 刑案下被调查或追踪，结果最了解基地组织、最擅长刑事手段的刑事探员被排除在搜寻之外。", "quote_en": "It is now clear that everyone involved was confused about the rules governing the sharing and use of information gathered in intelligence channels.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-luck": {"claim_id": "lt.rep-luck", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：即使搜寻早在 8 月 23 日开始，调查人员要在 9/11 之前找到 Mihdhar 与 Hazmi 也既需要技巧也需要运气；他们在美国用的是真名。", "quote_en": "the investigators would have needed luck as well as skill to find them prior to September 11 even if such searches had begun as early as August 23", "quote_zh": "即使这样的搜寻早在 8 月 23 日就开始，调查人员要在 9 月 11 日之前找到他们，也既需要技巧，也需要运气", "screen_locator": "The 9/11 Commission Report, 2004, p. 272", "review_state": "checked"}, "lt.rep-detain": {"claim_id": "lt.rep-detain", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：FBI 证人说即使找到二人也只能跟着他们上飞机，委员会认为这不对——二人可因移民违规或作为 Cole 案的重要证人被拘留，仅拘留本身就可能打乱计划。", "quote_en": "Both Hazmi and Mihdhar could have been held for immigration violations or as material witnesses in the Cole bombing case.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-failures-four": {"claim_id": "lt.rep-failures-four", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会在第 11 章开头把 9/11 暴露的失败归为四类：想象力、政策、能力和管理。", "quote_en": "We believe the 9/11 attacks revealed four kinds of failures: in imagination, policy, capabilities, and management.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-imagination": {"claim_id": "lt.rep-imagination", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会在“想象力”一节写道：想象力不是官僚机构通常具备的天赋，因此要把运用想象力的做法例行化、制度化。", "quote_en": "Imagination is not a gift usually associated with bureaucracies.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-nottried": {"claim_id": "lt.rep-nottried", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：冷战后几十年里美国政府精心发展出来的预警方法没有失败，只是没有被真正用来分析当时最可能发动突袭的敌人。", "quote_en": "did not fail; instead, they were not really tried", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.rep-notshared-inadvertent": {"claim_id": "lt.rep-notshared-inadvertent", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会在“管理”一节总括：信息没有被共享，有时是无意的，有时是因为对法律的误解；分析没有汇总，有效行动没有展开；交接常在分隔国内外机构的鸿沟上丢失。", "quote_en": "Information was not shared, sometimes inadvertently or because of legal misunderstandings.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-physician": {"claim_id": "lt.rep-physician", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会用医院比喻管理缺位：各机构像一群专科医生，各自开检查、找症状、开药，缺的是确保他们作为团队工作的主治医生。", "quote_en": "What is missing is the attending physician who makes sure they work as a team.", "quote_zh": "缺的是一位主治医生，由他确保大家作为一个团队工作。", "screen_locator": "The 9/11 Commission Report, 2004, p. 353", "review_state": "checked"}, "lt.rep-opps": {"claim_id": "lt.rep-opps", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会列出十个“行动机会”，前六个都与 CIA 与 FBI 之间的信息有关，第一个是：2000 年 1 月 CIA 没有把 Mihdhar 放上观察名单，也没有在得知他持有效美国签证时通知 FBI。", "quote_en": "January 2000: the CIA does not watchlist Khalid al Mihdhar or notify the FBI when it learned Mihdhar possessed a valid U.S. visa.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.rep-watchlist-limit": {"claim_id": "lt.rep-watchlist-limit", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：基地组织能适应部分成员入境失败，所以即使观察名单阻止或提醒了 Hazmi 与 Mihdhar 入境，委员会也不认为仅靠它就能阻止 9/11；这些未来的劫机者当时没有一个是飞行员。", "quote_en": "Al Qaeda adapted to the failure of some of its operatives to gain entry into the United States.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-symptoms": {"claim_id": "lt.rep-symptoms", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会在第 13 章明说：公众评论里的“观察名单”“信息共享”“连点成线”这些标签过于狭窄，描述的是症状，不是病根。", "quote_en": "In chapter 11 we explained that these labels are too narrow. They describe the symptoms, not the disease.", "quote_zh": "我们在第 11 章说明过，这些标签太窄。它们描述的是症状，不是病根。", "screen_locator": "The 9/11 Commission Report, 2004, p. 400", "review_state": "checked"}, "lt.rep-noowner": {"claim_id": "lt.rep-noowner", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会说，在每个例子里，没有人牢牢负责管理个案，并能从政府任何地方调取相关情报、跨机构分配责任、跟踪进展、迅速把障碍提到能解决的层级；责任与问责是分散的。", "quote_en": "no one was firmly in charge of managing the case and able to draw relevant intelligence from anywhere in the government", "quote_zh": "没有人牢牢负责管理这个案子，并能从政府的任何地方调取相关情报", "screen_locator": "The 9/11 Commission Report, 2004, p. 400", "review_state": "checked"}, "lt.rep-structures": {"claim_id": "lt.rep-structures", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：9/11 故事中最令人难过的一面是许多官员出色的个人努力，在可能性的边界上挣扎而往往无功；好人能克服坏结构，但他们本不该这样。", "quote_en": "Good people can overcome bad structures.They should not have to.", "quote_zh": null, "screen_locator": null, "review_state": "needs-fix"}, "lt.rep-needtoknow": {"claim_id": "lt.rep-needtoknow", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会在“信息共享”一节写道：这些故事的共同点是一个要求先证明“需要知道”才能共享的系统。", "quote_en": "What all these stories have in common is a system that requires a demonstrated “need to know” before sharing.", "quote_zh": "这些故事的共同之处，是一套要求先证明“需要知道”才肯共享的制度。", "screen_locator": "The 9/11 Commission Report, 2004, p. 417", "review_state": "checked"}, "lt.rep-culture": {"claim_id": "lt.rep-culture", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会提出文化转换：把各机构觉得自己拥有所收集信息的文化，换成各机构觉得对信息负有义务、要把信息提供出来以回报纳税人的文化。", "quote_en": "The culture of agencies feeling they own the information they gathered at taxpayer expense must be replaced by a culture in which the agencies instead feel they have a duty to the information", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-incentive": {"claim_id": "lt.rep-incentive", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：各机构的激励结构反对共享，共享要冒（刑事、民事和内部行政处分的）风险而几乎没有回报，不共享则不受惩罚；各机构奉行的是“need-to-know”的信息保护文化，而不是“need-to-share”的整合文化。", "quote_en": "Each agency’s incentive structure opposes sharing, with risks (criminal, civil, and internal administrative sanctions) but few rewards for sharing information.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-recommend": {"claim_id": "lt.rep-recommend", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "该节的建议是：信息程序应当提供共享的激励，以恢复安全与共享知识之间更好的平衡。", "quote_en": "Information procedures should provide incentives for sharing, to restore a better balance between security and shared knowledge.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.rep-network": {"claim_id": "lt.rep-network", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会提出的网络设计：把数据与其来源和方法在报告生成时分开，先以最可共享的形式发布；任何用户需要细节时可进一步查询，由网络规则决定放行或拒绝并留下审计轨迹；把各机构的数据库做成可跨机构搜索的分散式网络，用“信息权限管理”控制对数据的访问，而不是对整个网络的访问。", "quote_en": "secrets are protected through the design of the network and an “information rights management” approach that controls access to the data, not access to the whole network", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-unsent": {"claim_id": "lt.ig-unsent", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "CIA 监察长（2005 年 6 月）写道：2000 年 1 月 5 日，一名派驻反恐中心的 FBI 官员起草了一份经正规渠道从 CIA 发给 FBI、关于二人行程的消息，显然因为格式不对或需要编辑，这份消息从未发出。", "quote_en": "Apparently because it was in the wrong format or needed editing, the message was never sent.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-cannot-confirm": {"claim_id": "lt.ig-cannot-confirm", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "监察长写道：同日另一名反恐中心官员发出内部电报，称信息和 Mihdhar 的旅行证件已转给 FBI；该官员不记得是怎么转的，监察长小组无法确认是否转过，也找不到任何人检查过 FBI 是否收到。", "quote_en": "The Team has not been able to confirm that the information was passed, or that it was not passed.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-march2000": {"claim_id": "lt.ig-march2000", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "监察长写道：2000 年 3 月两个 CIA 外站发电报称 Hazmi 等已前往美国，电报明确称其为“UBL 的伙伴”；小组找不到证据，也没听任何一方声称，这条信息以任何方式与 FBI 共享过，反恐中心里也没有人采取适当的行动。", "quote_en": "The Team has found no evidence, and heard no claim from any party, that this information was shared in any manner with the FBI", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-notreluctance": {"claim_id": "lt.ig-notreluctance", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "CIA 监察长在“更广的信息共享问题”一节写道：国会联合调查认为 CIA 的共享问题源于使命、法定权限和文化的差异，保护来源与方法造成了不愿共享；监察长小组的发现在许多方面相似，但小组认为本案的系统性失败不在于不愿共享，而在于为促进信息交换而设的流程（包括派驻人员项目）执行、指引和监督都差。", "quote_en": "the Team believes the systemic failures in this case do not lie in reluctance to share. Rather, the basic problems were poor implementation, guidance, and oversight of processes established to foster the exchange of information", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-detailee": {"claim_id": "lt.ig-detailee", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "监察长写道：反恐中心与 UBL Station 的花名册里有来自 FBI、NSA、FAA、国务院的派驻人员；许多 CIA 管理者认为派驻人员有责任向原单位传信息，而多数派驻人员认为自己是在做 CTC 官员，既没时间也没责任充当与原单位的联络；小组认定派驻人员在信息共享上的责任存在根本性的含糊，从未被明确界定。", "quote_en": "The Team found, at a minimum, that there were fundamental ambiguities about the responsibilities of the detailees as they related to information sharing", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-systemic": {"claim_id": "lt.ig-systemic", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "监察长写道：2000-2001 年这么多人没有为 Hazmi 与 Mihdhar 做观察名单提名，反映的是系统性崩溃，由工作量过大、职责含糊和项目管理不善造成；基本上没有一套连贯运转的观察名单项目。", "quote_en": "That so many individuals failed to act in this case reflects a systemic breakdown—a breakdown caused by excessive workload, ambiguities about responsibilities, and mismanagement of the program.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.ig-surveil": {"claim_id": "lt.ig-surveil", "unit": "lt", "source_id": "lt:S09", "claim_type": "official-record", "statement_zh": "监察长写道：及早通报 FBI，加上 CIA 与 FBI 良好的后续行动，本可能对 Mihdhar 与 Hazmi 形成监视，进而可能获得飞行训练、资金和同谋者联系的信息。", "quote_en": "Informing the FBI and good operational followthrough by CIA and FBI might have resulted in surveillance of both al-Mihdhar and al-Hazmi.", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.inf-parallel": {"claim_id": "lt.inf-parallel", "unit": "lt", "source_id": "lt:S08", "claim_type": "inference", "statement_zh": "本系列若把 9/11 与 Palantir 连起来，现有一手文本只支持一处文字上的平行：委员会 pp.417-418 的设计原则（按数据而不是按整个网络控制访问，查询留审计轨迹）与 Qureshi 描述的平台安全控制（基于角色的访问控制、行级策略、安全标记、审计日志，S01 line 156）相近；没有任何一手来源说 Palantir 的设计源自委员会报告或这本书。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "lt.unres-book-text": {"claim_id": "lt.unres-book-text", "unit": "lt", "source_id": "lt:S11", "claim_type": "unresolved", "statement_zh": "书中关于 CIA 与 FBI 信息共享的正文无法直接核实：Salon 2006 年 8 月 30 日的书评转引了它称出自书中的两句话，其措辞与 The Agent 里的对应句子不同——书评中是“bizarre trend ... to hide”，文章里是“strange trend ... toward hiding”；书评中是“政府已有但拒绝分享的信息”，文章里是“其他美国官员拒绝分享的信息”。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "iu.1e-four-weeks": {"claim_id": "iu.1e-four-weeks", "unit": "iu", "source_id": "main:portigal-1e-excerpt", "claim_type": "direct-source", "statement_zh": "第 1 版第 3 章：一个运动服装网购研究原定六周，团队花了四周在越来越多的干系人之间协商要研究哪几类顾客；作者说这四周累人，但让团队解了套、研究得以推进。", "quote_en": "we spent four weeks (of what was supposed to be a six-week project) actively negotiating, among an ever-increasing set of stakeholders, the basic archetypes of customers to look at.", "quote_zh": null, "screen_locator": "第 1 版 · 第 3 章", "review_state": "checked"}, "iu.1e-hypotheses": {"claim_id": "iu.1e-hypotheses", "unit": "iu", "source_id": "main:portigal-1e-excerpt", "claim_type": "direct-source", "statement_zh": "第 1 版第 3 章：团队问自己顾客是谁时，会冒出各种脱节：冒充事实的假设、愿望和集体幻觉。", "quote_en": "this question surfaces any number of disconnects: hypotheses masquerading as facts, aspirations, and mass hallucinations.", "quote_zh": null, "screen_locator": "第 1 版 · 第 3 章", "review_state": "checked"}, "iu.1e-recruiting-data": {"claim_id": "iu.1e-recruiting-data", "unit": "iu", "source_id": "main:portigal-1e-excerpt", "claim_type": "direct-source", "statement_zh": "第 1 版第 3 章：招不到预期中的受访者，这件事本身就是数据。", "quote_en": "If it’s very challenging to find the people that you expect (or are expected) to do research with, that’s data.", "quote_zh": null, "screen_locator": "第 1 版 · 第 3 章", "review_state": "checked"}, "iu.1e-toc-worldview": {"claim_id": "iu.1e-toc-worldview", "unit": "iu", "source_id": "main:portigal-1e-excerpt", "claim_type": "direct-source", "statement_zh": "第 1 版目录里的小节标题包括：Check Your Worldview at the Door（第 2 章）、Use Their Language 与 Assume Your Participant Makes Sense（第 6 章）。", "quote_en": "Check Your Worldview at the Door", "quote_zh": null, "screen_locator": "第 1 版 · 目录", "review_state": "checked"}, "iu.1e-toc-artifacts": {"claim_id": "iu.1e-toc-artifacts", "unit": "iu", "source_id": "main:portigal-1e-excerpt", "claim_type": "direct-source", "statement_zh": "第 1 版目录里已有 A Guide to Participating in Fieldwork（第 5 章，书页 69）、Debriefing After the Interview（第 7 章，书页 115）与 Create a Topline Report（第 9 章，书页 137），与作者 2011–2012 年发布的现场说明、复盘表和顶部摘要样例对应。", "quote_en": "A Guide to Participating in Fieldwork", "quote_zh": null, "screen_locator": "第 1 版 · 目录", "review_state": "checked"}, "iu.2e-third-parties": {"claim_id": "iu.2e-third-parties", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "第 2 版第 1 章插叙 Uncover Misalignment Early：第一场启动工作坊里，项目发起人停下来问“我们说的 third parties 到底指什么”；双方都以为对方知道。", "quote_en": "In the first workshop, the main project sponsor halted the proceeding to ask “Now, what do we mean by ‘third parties?’” I assumed they knew, and they assumed I knew!", "quote_zh": "在第一场工作坊上，项目的主要发起人叫停议程，问道：“那么，我们说的‘第三方’到底指什么？”我以为他们知道，他们以为我知道！", "screen_locator": "第 2 版 · 第 1 章", "review_state": "checked"}, "ov.qureshi-language": {"claim_id": "ov.qureshi-language", "unit": "ov", "source_id": "main:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 写道，FDE 的成效直接取决于能多快学会说客户的语言、深入弄懂客户的业务。", "quote_en": "Your effectiveness directly correlates to how quickly you can learn to speak the customer’s language and really drill down into how their business works.", "quote_zh": "你的成效，直接取决于你能多快学会说客户的语言、真正弄懂他们的业务怎样运转。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "gtd.cat-food": {"claim_id": "gtd.cat-food", "unit": "gtd", "source_id": "gtd:S-FERRISS-384", "claim_type": "direct-source", "statement_zh": "Allen 在 2019 年 Tim Ferriss 访谈里说，脑子里记事的那部分没有过去和将来的概念，会以为你一天二十四小时都该去买猫粮，所以凌晨三点把你叫醒。", "quote_en": "thinks you should be buying cat food 24 hours a day, or hiring a vice president 24 hours a day. That’s why it wakes you up at 3:00 in the morning.", "quote_zh": null, "screen_locator": "David Allen, The Tim Ferriss Show #384, 2019", "review_state": "checked"}, "pr.version-2015-match": {"claim_id": "pr.version-2015-match", "unit": "pr", "source_id": "main:dalio-bwater-2015", "claim_type": "direct-source", "statement_zh": "2015 年夏天 Bridgewater 网站上公开的 Principles PDF（123 页，© 2011，2012-01 至 2016-03-04 期间提供）与本系列读的 2016 年重排版（106 页）正文基本一致：按词比对的序列相似度 0.936，差异主要是重排时挪动的脚注；本集引用的原则编号与原话在两份中都有。", "quote_en": "Never make any important decisions without asking at least three believable people.", "quote_zh": null, "screen_locator": "本系列比对 · Ray Dalio, Principles, PDF © 2011 · 2015 公开版与 2016 重排版", "review_state": "checked"}, "lt.flight77": {"claim_id": "lt.flight77", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "9/11 委员会报告第 1 章：2001 年 9 月 11 日早上，Khalid al Mihdhar 与 Nawaf al Hazmi 在华盛顿杜勒斯机场为美国航空 77 号航班办理登机，报告称这五人为劫机者；报告插图说明称 77 号航班撞击了五角大楼。", "quote_en": "Khalid al Mihdhar and Majed Moqed, checked in at the American Airlines ticket counter for Flight 77, bound for Los Angeles.", "quote_zh": null, "screen_locator": "The 9/11 Commission Report, 2004, p. 3", "review_state": "checked"}, "ov.qureshi-cowen": {"claim_id": "ov.qureshi-cowen", "unit": "ov", "source_id": "main:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 引 Tyler Cowen 的“context is that which is scarce”，称它是 FDE 模式的基础洞见：到客户现场，拿到的是对方工作方式的隐性知识，不只是企业软件惯用的压平了的需求清单。", "quote_en": "you capture the tacit knowledge of how they work, not just the flattened ‘list of requirements’ model that enterprise software typically relies on.", "quote_zh": "你拿到的是他们怎样工作的隐性知识，不只是企业软件通常依赖的那种压平了的“需求清单”。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "ov.qureshi-impro-chain": {"claim_id": "ov.qureshi-impro-chain", "unit": "ov", "source_id": "main:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 在解释 Impro 时说：不懂这些（地位的机制），就不太可能在客户环境里成功，也就不太可能接进客户数据、让人用你的软件，那就意味着失败。", "quote_en": "If you didn’t know all this, you were unlikely to succeed in a customer environment. Which meant you were unlikely to integrate customer data or get people to use your software. Which meant failure.", "quote_zh": "不懂这些，你就不太可能在客户那里成功；也就不太可能接进客户的数据，或者让人用上你的软件；那就意味着失败。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "pr.tested-40-years": {"claim_id": "pr.tested-40-years", "unit": "pr", "source_id": "pr:dalio-2011-pdf", "claim_type": "direct-source", "statement_zh": "Part 3 开头 Dalio 写道，这套做法的理论已经过去四十年检验并且有效；文件没有给出外部数据。", "quote_en": "Second, this theory has been tested over the last 40 years and has worked.", "quote_zh": "其次，这套理论在过去四十年里经过了检验，而且行之有效。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2016 重排版）, p. 43", "review_state": "checked"}, "im.preview-scope": {"claim_id": "im.preview-scope", "unit": "im", "source_id": "im:impro-routledge-2012", "claim_type": "direct-source", "statement_zh": "本系列读到的 Impro 正文是 Routledge 2012 年重印本在谷歌图书上的出版方预览：整页可读的是第 42–44、46、50、55–56 页，都在 Status 一章；其余页只有检索片段。", "quote_en": "", "quote_zh": null, "screen_locator": "Impro, Routledge 2012 重印本，谷歌图书预览", "review_state": "checked"}, "iu.need-tolerated": {"claim_id": "iu.need-tolerated", "unit": "iu", "source_id": "iu:portigal-ch1-2e", "claim_type": "direct-source", "statement_zh": "Portigal 提醒：你观察到的需求，可能正是顾客完全忍得了的东西。", "quote_en": "What you observe as a need may actually be something that your customer is perfectly tolerant of.", "quote_zh": "你观察到的需求，可能正是顾客完全忍得了的东西。", "screen_locator": "Steve Portigal, Interviewing Users, 2nd ed., 2023, ch. 1", "review_state": "checked"}, "lt.rep-late-august": {"claim_id": "lt.rep-late-august", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：2001 年 8 月 21–22 日，FBI 分析员查到 Mihdhar 已经入境美国、Hazmi 没有离境记录，决定把人找出来；8 月 24 日两人列入 TIPOFF 观察名单；给纽约外勤办公室的线索 8 月 23 日起草，8 月 28 日才发出。", "quote_en": "They decided that if Mihdhar was in the United States, he should be found.", "quote_zh": "她们认定，Mihdhar 如果在美国，就该把他找出来。", "screen_locator": "The 9/11 Commission Report, 2004, p. 270", "review_state": "checked"}, "lt.rep-june11-photos": {"claim_id": "lt.rep-june11-photos", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会写道：6 月 11 日在纽约，FBI 分析员（化名 Jane）带去吉隆坡监视照片给 Cole 案探员看，问他们认不认得照片里的 Quso；探员追问照片为什么拍、这些人为什么被跟踪、其余照片在哪里。", "quote_en": "Why were they taken? Why were these people being followed? Where are the rest of the photographs?", "quote_zh": "照片为什么拍？这些人为什么被跟踪？其余的照片在哪里？", "screen_locator": "The 9/11 Commission Report, 2004, p. 269", "review_state": "checked"}, "lt.eye-soufan-fbi": {"claim_id": "lt.eye-soufan-fbi", "unit": "lt", "source_id": "lt:S06", "claim_type": "official-record", "statement_zh": "9/11 纪念馆对谈的主持人介绍：Ali Soufan 曾在 FBI 任职，在纽约外勤办公室的联合反恐特遣队协调国内外反恐行动，经手过东非使馆爆炸案、科尔号袭击案和九一一相关案件。", "quote_en": "Soufan had a distinguished career in the FBI, including serving on the Joint Terrorism Task Force, FBI New York office", "quote_zh": "Soufan 在 FBI 有过出色的职业生涯，包括在 FBI 纽约办公室的联合反恐特遣队任职", "screen_locator": "9/11 Memorial panel, 2018", "review_state": "checked"}, "lt.book-knopf-2006": {"claim_id": "lt.book-knopf-2006", "unit": "lt", "source_id": "lt:S14", "claim_type": "direct-source", "statement_zh": "The Looming Tower 由 Lawrence Wright 撰写，2006 年由 Knopf 出版精装本。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.book-2017": {"claim_id": "pr.book-2017", "unit": "pr", "source_id": "main:openlibrary-principles-2017", "claim_type": "direct-source", "statement_zh": "正式出版的 Principles: Life and Work 由 Simon & Schuster 于 2017 年 9 月出版，592 页，篇幅是 2011 年版 PDF 的数倍；本系列没有读这本书。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "pr.dalio-founded-1975": {"claim_id": "pr.dalio-founded-1975", "unit": "pr", "source_id": "main:dalio-bwater-2015", "claim_type": "direct-source", "statement_zh": "Dalio 在 Principles 里写道，他 1975 年创立了 Bridgewater。", "quote_en": "So in 1975, after a quick two-year stint on Wall Street after school, I started Bridgewater.", "quote_zh": "于是在 1975 年，毕业后在华尔街短暂待了两年，我创立了 Bridgewater。", "screen_locator": "Ray Dalio, Principles, PDF © 2011（2015 公开版）", "review_state": "checked"}, "ov.saraf_best_part": {"claim_id": "ov.saraf_best_part", "unit": "ov", "source_id": "ov:saraf-alums", "claim_type": "eyewitness", "statement_zh": "Saraf 写道：这套做法最好的一面，是只要看着收件箱里的文件夹，就能实时掌握公司里发生的每件事。", "quote_en": "The best part about this is that you could keep a running pulse of everything that happens at the company in real-time just by watching folders in your inbox.", "quote_zh": "最好的一面是，只要看着收件箱里的文件夹，就能实时掌握公司里发生的每件事。", "screen_locator": "Sanjay Saraf, Lessons from Palantir Alums, 2024", "review_state": "checked"}, "gtd.weekly-review-get-clear": {"claim_id": "gtd.weekly-review-get-clear", "unit": "gtd", "source_id": "gtd:S-DAC-PDF-WEEKLY", "claim_type": "direct-source", "statement_zh": "官方每周回顾清单（2015-05-20 版）第一组 Get Clear：收拢零散的纸张材料、把收件处处理到零、清空脑子；第二组 Get Current：逐张查看下一步行动、日历、等待和项目清单。", "quote_en": "GET “IN” TO ZERO", "quote_zh": null, "screen_locator": null, "review_state": "checked"}, "ov.qureshi-cowen-line": {"claim_id": "ov.qureshi-cowen-line", "unit": "ov", "source_id": "main:qureshi-reflections", "claim_type": "eyewitness", "statement_zh": "Qureshi 引 Tyler Cowen 的话“context is that which is scarce”，说这可以算 FDE 模式的基础洞见。", "quote_en": "Tyler Cowen has a wonderful saying, ‘context is that which is scarce’, and you could say it’s the foundational insight of this model.", "quote_zh": "Tyler Cowen 有句妙语：“情境才是稀缺的东西。”可以说，这就是这套模式的基础洞见。", "screen_locator": "Nabeel Qureshi, Reflections on Palantir, 2024", "review_state": "checked"}, "im.site-royal-court-post": {"claim_id": "im.site-royal-court-post", "unit": "im", "source_id": "im:keithjohnstone-site", "claim_type": "direct-source", "statement_zh": "Johnstone 官方网站称他曾任伦敦皇家宫廷剧院的副总监；国际 Theatresports 协会的简介写他 1956–1966 年在该剧院任首席审稿人、主持剧院工作室，后成为副总监。", "quote_en": "He was Associate Director of London’s Royal Court Theatre.", "quote_zh": "他曾任伦敦皇家宫廷剧院的副总监。", "screen_locator": "keithjohnstone.com", "review_state": "checked"}, "ov.s1-karp-ceo": {"claim_id": "ov.s1-karp-ceo", "unit": "ov", "source_id": "ov:palantir-s1", "claim_type": "official-record", "statement_zh": "Palantir 的 S-1 称 Alexander Karp 是公司创始人之一、首席执行官。", "quote_en": "Alexander Karp, one of our founders and our Chief Executive Officer", "quote_zh": "Alexander Karp，我们的创始人之一、首席执行官", "screen_locator": "Palantir Technologies, Form S-1, 2020", "review_state": "checked"}, "lt.rep-passport-jan2000": {"claim_id": "lt.rep-passport-jan2000", "unit": "lt", "source_id": "lt:S08", "claim_type": "official-record", "statement_zh": "委员会注 44 引 2000 年 1 月 4 日的 CIA 电报：Mihdhar 的沙特护照（内有赴美签证）被复印并转回 CIA 总部。", "quote_en": "His Saudi passport—which contained a visa for travel to the United States—was photocopied and forwarded to CIA headquarters.", "quote_zh": "他的沙特护照（内有赴美签证）被复印，转回了 CIA 总部。", "screen_locator": "The 9/11 Commission Report, 2004, ch. 6, n. 44", "review_state": "checked"}, "ov.mabrey-title": {"claim_id": "ov.mabrey-title", "unit": "ov", "source_id": "ov:stratechery-2023", "claim_type": "official-record", "statement_zh": "Stratechery 2023 年访谈的标题称 Ted Mabrey 为 Palantir 的全球商务负责人。", "quote_en": "Head of Global Commercial Ted Mabrey", "quote_zh": "全球商务负责人 Ted Mabrey", "screen_locator": "Stratechery, 2023", "review_state": "checked"}, "gtd.no-independent-evaluation": {"claim_id": "gtd.no-independent-evaluation", "unit": "gtd", "source_id": "main:series-search-2026-10", "claim_type": "inference", "statement_zh": "本系列读到的 GTD 材料里，方法成效的证据只有作者自己的叙述和客户轶事，没有找到独立的研究或评估。", "quote_en": "", "quote_zh": null, "screen_locator": null, "review_state": "checked-with-limits"}};
